window.marchStdlib = window.marchStdlib || {};
window.marchStdlib["cluster_node.march"] = "-- ClusterNode: one running cluster node -- it joins from seed addresses, runs\n-- SWIM continuously over one persistent authenticated connection pair per\n-- peer, and tells subscribers when a peer is suspected, dead or back.\n--\n-- Design: specs/progress/2026-09-18-cluster-node-service.md. The parts it\n-- assembles were already here (Membership/Swim/SwimDriver, NetKernel's\n-- handshake, PeerReader, NodeQueue); what was missing was a node that stays\n-- up and uses them together.\n--\n-- Shape: a PURE core (`core_*`, `CnState -> ... -> (CnState, List(CnEffect))`,\n-- unit-tested under the eval harness, which cannot run sockets) inside ONE\n-- actor (`ClusterNodeActor`) that owns the state and performs the effects, plus a few\n-- tasks around it:\n--\n--   acceptor   blocking tcp_accept loop; each connection is handshaked in its\n--              own task (deadline-bounded) and reported as `Accepted`\n--   dialer     one task per attempt: connect_timeout + handshake, control\n--              then data, reported as `Dialed` / `DialFailed`\n--   readers    one per connection (PeerReader.serve): control frames go to\n--              the actor as `CtlFrame`; end of stream is `LinkClosed(id, gen)`\n--   ticker     `Tick` every tick_ms; the SWIM period, the redial backoff and\n--              the stale-dial expiry all run off it\n--   (the readers, the ticker and the acceptor move to a new code epoch\n--   after a hot deploy: see \"moving to a new code epoch\" below)\n--   CtlWriter  one per peer: EVERY write to a control socket goes through it\n--              (two writers on one socket interleave frames)\n--\n-- Connections. One control + one data connection per peer, reused by\n-- everything. Two nodes dialling each other at once each end up with two\n-- pairs; both keep the pair dialled by the LOWER node_id (a symmetric rule,\n-- no message needed). Each pair has a generation; a close from a replaced\n-- generation is ignored. A closed connection is a HINT: the member goes\n-- Suspect and is redialled at once; a redial REFUSED (nothing listening) is\n-- definite and makes it Dead. When SWIM declares a node Dead the node shuts\n-- both its connections. Healing: SWIM never probes a Dead member, so the\n-- node redials every Dead member's advertised address on a backoff; when a\n-- redial lands, MEMBERS_SYNC in both directions lets each side refute what\n-- the other believed.\n--\n-- Names (the registry replica). The node holds a GlobalRegistry replica: a\n-- local `register` is pushed at once to every linked peer (REGISTRY_SYNC_RESP\n-- with the changed leaves), every new link exchanges the whole registry, and\n-- a 30 s anti-entropy round (REGISTRY_SYNC_REQ with the root hash) repairs\n-- what a push missed. A registration's clock is the name's current clock\n-- with our slot bumped, so a takeover after seeing a binding is causally\n-- newer and never falls to the tiebreak. `lookup` sees only VISIBLE\n-- bindings: one whose holder is Dead here, or whose holder has restarted\n-- since (a stale creation), is hidden -- not tombstoned; it reappears if the\n-- holder rejoins with the same creation. The owner tombstones its own\n-- stale-creation bindings when it learns of them. A global name is AP, not a\n-- lock: during a partition both sides can hold one; after the heal the CRDT\n-- picks one winner everywhere, and the loser's watchers get `Lost`.\n--\n-- Everything the node knows about members and names is also mirrored into\n-- Vaults (`members`, `addr_of`, `lookup`), so readers need no round trip to\n-- the actor.\n--\n-- The node is a capability: `start(io, cfg)` returns a `Cap(ClusterNode.Live)`\n-- whose dictionary (`ClusterOps`) every public operation calls through, and a test\n-- can `attach(io, ops)` its own (D35; see \"the capability\" below).\nmod ClusterNode do\n  needs IO\n  needs IO.NetListen\n  needs IO.NetConnect\n  needs IO.Spawn\n  needs IO.Mut\n  needs IO.Clock\n  needs IO.Process\n  needs IO.Random\n\n  -- \u2500\u2500 configuration \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- `advertise` is the \"host:port\" peers dial; `seeds` are \"host:port\" too.\n  -- `creation` must grow across restarts of the same node (the default is\n  -- the start time in ms). Durations in ms.\n  --\n  -- `auth` is how the node authenticates peers: `ClusterAuth.Secret(secret)`\n  -- (what `config` sets from [secret]) or `ClusterAuth.Certified(creds)`, a\n  -- node certificate (`config_from_env` with MARCH_NODE_CERT, or a record\n  -- update). `secret` is kept for code that reads it; the handshake uses\n  -- `auth`.\n  --\n  -- `cert_files` (certificate mode): the files the node re-reads its\n  -- certificate and key from while it runs, replacing them live when they\n  -- change (see `replace_cert`); `config_from_env` sets it.\n  type CnConfig = { name : String, listen_port : Int, advertise : String, seeds : List(String),\n                    secret : String, creation : Int, swim : Swim.Config, period_ms : Int,\n                    tick_ms : Int, redial_min_ms : Int, redial_max_ms : Int,\n                    dial_timeout_ms : Int, handshake_timeout_ms : Int, auth : ClusterAuth.Auth,\n                    revocations : List(NodeCert.SignedRevocation), cert_files : Option(CertFiles),\n                    tombstone_grace_ms : Int }\n\n  -- Where a certificate-mode node re-reads its certificate while it runs:\n  -- [cert] the certificate file, [key] the key file (\"\" when the key was\n  -- given as a value: it is then kept), checked every [poll_ms].\n  type CertFiles = { cert : String, key : String, poll_ms : Int }\n\n  doc \"\"\"\n  A configuration with the defaults: SWIM period 1 s, ack timeout 500 ms,\n  suspect timeout 3 s, 2 indirect helpers, tick 100 ms, redial backoff\n  200 ms doubling to 5 s, dial and handshake timeouts 2 s. [advertise] \"\"\n  means `127.0.0.1:<listen_port>`. The SWIM timings trade detection speed\n  for false suspicions on a loaded host (a 300 ms ack timeout suspected\n  healthy peers on a busy CI runner); override `swim` / `period_ms` with a\n  record update to tune them. The environment can move the three SWIM\n  defaults without a rebuild: `MARCH_SWIM_PERIOD_MS`, `MARCH_SWIM_ACK_MS`\n  and `MARCH_SWIM_SUSPECT_MS` (each a positive integer; anything else keeps\n  the default). A record update still wins over them.\n\n  A name unregistered anywhere in the cluster leaves a tombstone in every\n  replica of the registry; it is dropped `tombstone_grace_ms` after it was\n  first seen (default 3 hours, `MARCH_REGISTRY_TOMBSTONE_GRACE_MS`). Keep it\n  well above the longest partition the cluster should heal from: a partition\n  longer than that can bring back a binding whose holder is gone, which the\n  node service then hides and its owner unregisters again.\n  \"\"\"\n  fn config(name : String, listen_port : Int, advertise : String, seeds : List(String),\n            secret : String, creation : Int) : CnConfig do\n    let adv = if String.is_empty(advertise) do \"127.0.0.1:\" ++ int_to_string(listen_port) else advertise end\n    let swim = Swim.config(env_ms(\"MARCH_SWIM_ACK_MS\", 500), env_ms(\"MARCH_SWIM_SUSPECT_MS\", 3000), 2)\n    { name: name, listen_port: listen_port, advertise: adv, seeds: seeds, secret: secret,\n      creation: creation, swim: swim, period_ms: env_ms(\"MARCH_SWIM_PERIOD_MS\", 1000), tick_ms: 100,\n      redial_min_ms: 200, redial_max_ms: 5000, dial_timeout_ms: 2000, handshake_timeout_ms: 2000,\n      auth: ClusterAuth.Secret(secret), revocations: Nil, cert_files: None,\n      tombstone_grace_ms: env_ms(\"MARCH_REGISTRY_TOMBSTONE_GRACE_MS\", 3 * 60 * 60 * 1000) }\n  end\n\n  -- A positive duration from the environment, or [dflt].\n  pfn env_ms(name : String, dflt : Int) : Int do\n    match String.to_int(env_or(name, \"\")) do\n      Ok(n) -> if n > 0 do n else dflt end\n      Err(_) -> dflt\n    end\n  end\n\n  pfn env_or(name : String, dflt : String) : String do\n    match System.env(name) do\n      Some(v) -> if String.is_empty(v) do dflt else v end\n      None -> dflt\n    end\n  end\n\n  -- An environment value, or -- when it names a readable file -- that\n  -- file's contents (keys and certificates are usually mounted as files).\n  pfn env_file(name : String) : String do\n    let v = env_or(name, \"\")\n    if String.is_empty(v) do \"\"\n    else if File.exists(v) do\n      match File.read(v) do\n        Ok(text) -> String.trim(text)\n        Err(_) -> v\n      end\n    else v end end\n  end\n\n  -- MARCH_NODE_CERT (and MARCH_NODE_KEY) as files to watch, when the\n  -- certificate was given as a file; MARCH_NODE_CERT_POLL_MS, default 10 s.\n  pfn cert_files_from_env() : Option(CertFiles) do\n    let cp = env_or(\"MARCH_NODE_CERT\", \"\")\n    if File.exists(cp) do\n      let kp = env_or(\"MARCH_NODE_KEY\", \"\")\n      let poll = match String.to_int(env_or(\"MARCH_NODE_CERT_POLL_MS\", \"\")) do\n        Ok(n) -> if n > 0 do n else 10000 end\n        Err(_) -> 10000\n      end\n      Some({ cert: cp, key: if File.exists(kp) do kp else \"\" end, poll_ms: poll })\n    else None end\n  end\n\n  doc \"\"\"\n  Certificate credentials for node [name] from their text forms: the node's\n  ed25519 secret key (hex, 64 bytes), its certificate (NodeCert text form)\n  and the operator public key (hex, 32 bytes). The certificate must verify\n  under the operator key now, name [name], and name the secret key's public\n  key -- a misconfigured node fails here, with the reason, rather than at\n  every handshake.\n  \"\"\"\n  fn credentials(name : String, key_hex : String, cert_text : String, operator_hex : String)\n      : Result(NodeCert.Credentials, String) do\n    match (NodeCert.key_from_hex(key_hex, 64), NodeCert.from_text(cert_text),\n           NodeCert.key_from_hex(operator_hex, 32)) do\n      (Err(e), _, _) -> Err(\"cluster_node: MARCH_NODE_KEY: \" ++ e)\n      (_, Err(e), _) -> Err(\"cluster_node: MARCH_NODE_CERT: \" ++ e)\n      (_, _, Err(e)) -> Err(\"cluster_node: MARCH_CLUSTER_OPERATOR_PUBKEY: \" ++ e)\n      (Ok(sk), Ok(signed), Ok(op)) ->\n        match NodeCert.verify(signed, op, unix_time_ms() / 1000) do\n          Err(e) -> Err(\"cluster_node: this node's own certificate: \" ++ e)\n          Ok(c) ->\n            if NodeCert.node_name(c.node) != name do\n              Err(\"cluster_node: the certificate names \" ++ c.node ++ \", but this node is \" ++ name)\n            else if c.pubkey != Bytes.to_hex(NodeCert.public_key(sk)) do\n              Err(\"cluster_node: MARCH_NODE_KEY is not the key the certificate names\")\n            else\n              Ok({ signed: signed, secret_key: sk, operator_pubkey: op, revoked: fn _ -> false })\n            end end\n        end\n    end\n  end\n\n  doc \"\"\"\n  Revocation tokens (`forge cluster revoke`'s output) separated by\n  whitespace or commas, each verified against the operator key.\n  \"\"\"\n  fn revocations_from_text(text : String, operator_pubkey : Bytes) : Result(List(NodeCert.SignedRevocation), String) do\n    let toks = List.filter(String.split(String.replace_all(String.replace_all(text, \"\\n\", \",\"), \" \", \",\"), \",\"),\n                           fn t -> not(String.is_empty(String.trim(t))))\n    List.fold_right(toks, Ok(Nil), fn (t, acc) ->\n      match acc do\n        Err(e) -> Err(e)\n        Ok(rest) ->\n          match NodeCert.revocation_from_text(t) do\n            Err(e) -> Err(e)\n            Ok(r) ->\n              match NodeCert.verify_revocation(r, operator_pubkey) do\n                Err(e) -> Err(e)\n                Ok(_) -> Ok(Cons(r, rest))\n              end\n          end\n      end)\n  end\n\n  doc \"\"\"\n  How a node named [name] authenticates, from the environment, for code that\n  opens connections of its own (SessionNode's direct runner, `run_<Role>`):\n  certificate mode when MARCH_NODE_CERT is set (with MARCH_NODE_KEY and\n  MARCH_CLUSTER_OPERATOR_PUBKEY, each a value or a file, and\n  MARCH_CLUSTER_REVOCATIONS for the revoked list), exactly as\n  `config_from_env` reads them; otherwise `ClusterAuth.Secret([secret])`.\n  \"\"\"\n  fn auth_from_env(name : String, secret : String) : Result(ClusterAuth.Auth, String) do\n    let cert = env_file(\"MARCH_NODE_CERT\")\n    let key = env_file(\"MARCH_NODE_KEY\")\n    if String.is_empty(cert) do\n      if String.is_empty(key) do Ok(ClusterAuth.Secret(secret))\n      else Err(\"cluster_node: MARCH_NODE_KEY is set but MARCH_NODE_CERT is not\") end\n    else\n      match credentials(name, key, cert, env_file(\"MARCH_CLUSTER_OPERATOR_PUBKEY\")) do\n        Err(e) -> Err(e)\n        Ok(creds) ->\n          match revocations_from_text(env_file(\"MARCH_CLUSTER_REVOCATIONS\"), creds.operator_pubkey) do\n            Err(e) -> Err(\"cluster_node: MARCH_CLUSTER_REVOCATIONS: \" ++ e)\n            Ok(revs) ->\n              let rs = List.map(revs, fn r -> r.rev)\n              Ok(ClusterAuth.Certified({ creds with revoked: fn c -> NodeCert.is_revoked(c, rs) }))\n          end\n      end\n    end\n  end\n\n  doc \"\"\"\n  Configuration from the environment: MARCH_NODE_NAME, MARCH_NODE_PORT,\n  MARCH_NODE_ADVERTISE (default 127.0.0.1:<port>), MARCH_CLUSTER_NODES\n  (seeds, host:port,...), MARCH_CLUSTER_SECRET, MARCH_NODE_CREATION (default:\n  the current time in ms, which grows across restarts on one host).\n\n  Certificate mode: with MARCH_NODE_CERT set, the node authenticates with a\n  certificate instead of the secret, and MARCH_NODE_KEY and\n  MARCH_CLUSTER_OPERATOR_PUBKEY must be set too (each may name a file\n  holding the value). MARCH_CLUSTER_SECRET is then ignored: both set means\n  certificate mode. Without MARCH_NODE_CERT the node runs in shared-secret\n  mode, as before (MARCH_NODE_KEY alone is an error, not a silent fallback).\n  MARCH_CLUSTER_REVOCATIONS (certificate mode; tokens or a file of them)\n  seeds the node's revocation list. When MARCH_NODE_CERT names a file, the\n  node re-reads it (and MARCH_NODE_KEY's file) every\n  MARCH_NODE_CERT_POLL_MS (default 10000) and replaces its certificate live\n  when they change (`replace_cert`; `cert_files`).\n  \"\"\"\n  fn config_from_env() : Result(CnConfig, String) do\n    match System.env(\"MARCH_NODE_NAME\") do\n      None -> Err(\"cluster_node: MARCH_NODE_NAME is not set\")\n      Some(name) ->\n        match String.to_int(env_or(\"MARCH_NODE_PORT\", \"\")) do\n          Err(_) -> Err(\"cluster_node: MARCH_NODE_PORT is not a port number\")\n          Ok(port) ->\n            let seeds = List.filter(List.map(String.split(env_or(\"MARCH_CLUSTER_NODES\", \"\"), \",\"), String.trim),\n                                    fn s -> not(String.is_empty(s)))\n            let creation = match String.to_int(env_or(\"MARCH_NODE_CREATION\", \"\")) do\n              Ok(c) -> c\n              Err(_) -> unix_time_ms()\n            end\n            let cfg = config(name, port, env_or(\"MARCH_NODE_ADVERTISE\", \"\"), seeds,\n                             env_or(\"MARCH_CLUSTER_SECRET\", \"march-cluster\"), creation)\n            let cert = env_file(\"MARCH_NODE_CERT\")\n            let key = env_file(\"MARCH_NODE_KEY\")\n            if String.is_empty(cert) do\n              if String.is_empty(key) do Ok(cfg)\n              else Err(\"cluster_node: MARCH_NODE_KEY is set but MARCH_NODE_CERT is not\") end\n            else\n              match credentials(name, key, cert, env_file(\"MARCH_CLUSTER_OPERATOR_PUBKEY\")) do\n                Err(e) -> Err(e)\n                Ok(creds) ->\n                  match revocations_from_text(env_file(\"MARCH_CLUSTER_REVOCATIONS\"), creds.operator_pubkey) do\n                    Err(e) -> Err(\"cluster_node: MARCH_CLUSTER_REVOCATIONS: \" ++ e)\n                    Ok(revs) -> Ok({ cfg with auth: ClusterAuth.Certified(creds), revocations: revs,\n                                            cert_files: cert_files_from_env() })\n                  end\n              end\n            end\n        end\n    end\n  end\n\n  doc \"\"\"\n  The node id a node named [name] runs under (`NodeIdentity.name_id`):\n  deterministic, so any node can compute a peer's id from its name. It is\n  what `node_id` answers for a node started with that name.\n  \"\"\"\n  -- A node's id: the hash of its public key (NodeIdentity.derive_id). Every\n  -- caller in the stdlib still passes \"pk-\" ++ name for the key; real keys\n  -- are an open question of the design.\n  fn node_id_of(name : String) : String do NodeIdentity.name_id(name) end\n\n  -- \u2500\u2500 raw sends (distributed-deploys step 11b) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- Raw primitives (`send_msg`, `queue_for` for `Node.enqueue`, and the\n  -- `route`/`route_type` receivers `@[remote]` and user code install) are\n  -- outside the protocol boundary: in CERTIFICATE mode a raw ACTOR_MSG\n  -- crosses a link only when the certificates at BOTH ends carry `raw_send`\n  -- (plan section 3, \"Raw primitives\"). A node's frames to itself (the\n  -- loopback) are never raw sends. Exempt, and enumerated here:\n  --   * session traffic: an ACTOR_MSG whose type tag is one of\n  --     `session_tags()` (before any \"#<sid>\" suffix), delivered to a route a\n  --     session opened with `route_session`. A session tag sent to a raw\n  --     route, or a raw tag sent to a session route, is refused.\n  --   * every frame on the CONTROL connection, which only ClusterNode writes\n  --     (`control_tags()`): SWIM, member gossip and sync, registry sync,\n  --     remote monitors, DELIVERY_FAILED, CREDIT, revocations. None of them\n  --     reaches a route.\n  -- A shared-secret node has no certificates and refuses nothing.\n\n  doc \"\"\"\n  The ACTOR_MSG type tags that are session traffic, exempt from raw-send\n  denial when they reach a session route: SessionAP's invitation, withdrawal\n  and answer, and SessionNode's frames (cluster sessions append \"#<sid>\").\n  The list is `NodeSend.session_tags()`, shared with the direct connections.\n  \"\"\"\n  fn session_tags() : List(String) do NodeSend.session_tags() end\n\n  doc \"Is [type_tag] session traffic (`session_tags()`, ignoring a \\\"#<sid>\\\" suffix)?\"\n  fn is_session_tag(type_tag : String) : Bool do NodeSend.is_session_tag(type_tag) end\n\n  doc \"\"\"\n  The control-connection frame tags, all ClusterNode's own and exempt from\n  raw-send denial: SWIM 0-3, REGISTRY_SYNC_REQ/RESP 5-6, MONITOR_REQ 7,\n  MONITOR_FIRE 8, DELIVERY_FAILED 10, CREDIT 11, MONITOR_ACK 12,\n  MEMBER_GOSSIP 13, MEMBERS_SYNC 14, REVOCATIONS 15, CERT_UPDATE 16. (9 is\n  ACTOR_MSG, the only frame on a data connection, and the only one checked.)\n  \"\"\"\n  fn control_tags() : List(Int) do [0, 1, 2, 3, 5, 6, 7, 8, 10, 11, 12, 13, 14, 15, 16] end\n\n  doc \"\"\"\n  May a raw ACTOR_MSG cross a link between a node holding [own] and a peer\n  that presented [peer]? Always in shared-secret mode ([own] None); in\n  certificate mode only when both certificates carry `raw_send`.\n  \"\"\"\n  fn raw_allowed(own : Option(NodeCert.Cert), peer : Option(NodeCert.Cert)) : Bool do\n    match own do\n      None -> true\n      Some(o) ->\n        if NodeCert.has_flag(o, \"raw_send\") do\n          match peer do\n            Some(p) -> NodeCert.has_flag(p, \"raw_send\")\n            None -> false\n          end\n        else false end\n    end\n  end\n\n  -- \u2500\u2500 what subscribers see \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  type NodeInfo = { node_id : String, name : String, addr : String, creation : Int, incarnation : Int }\n\n  type NodeEvent = NodeUp(NodeInfo) | NodeSuspect(NodeInfo) | NodeDead(NodeInfo, String) | NodeRejoined(NodeInfo)\n\n  -- What `on_security_event` subscribers see:\n  --   HandshakeRejected(who, why)  a peer's handshake refused: `who` is the\n  --                                address we dialled, or \"inbound\"\n  --   FrameRejected(node_id, n)    a frame from that peer failed its MAC and\n  --                                was dropped; n is the count on that\n  --                                connection (NetKernel.mac_failure_limit()\n  --                                of them close it)\n  --   RawSendRefused(node_id, what) a raw send to or from that peer refused\n  --                                (certificate mode, step 11b: this node's or\n  --                                the peer's certificate lacks `raw_send`);\n  --                                `what` is \"outbound <type tag>\", \"outbound\n  --                                queue\" or \"inbound <type tag>\"\n  --   CertReplaced(node_id, serial) a certificate replaced while running\n  --                                (`replace_cert`, step 12b): this node's\n  --                                own (node_id is this node's), or a linked\n  --                                peer's, from its CERT_UPDATE\n  --   CertRefused(node_id, why)    a replacement refused, the certificate in\n  --                                use kept: this node's own (a changed\n  --                                certificate file that does not check out,\n  --                                or `replace_cert`'s Err), or a peer's\n  --                                CERT_UPDATE\n  type SecurityEvent = HandshakeRejected(String, String) | FrameRejected(String, Int) | RawSendRefused(String, String)\n                     | CertReplaced(String, String) | CertRefused(String, String)\n\n  doc \"\"\"\n  A one-line, human-readable description of security event [ev], for logs:\n  e.g. `HandshakeRejected(\"10.0.0.2:9100\", \"bad proof\")` gives\n  `\"handshake with 10.0.0.2:9100 rejected: bad proof\"`.\n  \"\"\"\n  fn security_text(ev : SecurityEvent) : String do\n    match ev do\n      HandshakeRejected(who, why) -> \"handshake with \" ++ who ++ \" rejected: \" ++ why\n      FrameRejected(id, n) -> \"frame from \" ++ id ++ \" failed its MAC (\" ++ int_to_string(n) ++ \" on that connection)\"\n      RawSendRefused(id, what) -> \"raw send refused (\" ++ what ++ \"): no raw_send between this node and \" ++ id\n      CertReplaced(id, serial) -> \"certificate of \" ++ id ++ \" replaced (serial \" ++ serial ++ \")\"\n      CertRefused(id, why) -> \"certificate replacement for \" ++ id ++ \" refused: \" ++ why\n    end\n  end\n\n  doc \"The `NodeInfo` subscribers see for membership entry [m]: its id, name, address, creation and incarnation.\"\n  fn info_of(m : Member) : NodeInfo do\n    { node_id: m.node_id, name: m.name, addr: m.addr, creation: m.creation, incarnation: m.incarnation }\n  end\n\n  doc \"\"\"\n  A one-line description of membership event [ev], naming the node by its\n  name: `\"<name> up\"`, `\"<name> suspect\"`, `\"<name> dead: <why>\"` or\n  `\"<name> rejoined\"`.\n  \"\"\"\n  fn event_text(ev : NodeEvent) : String do\n    match ev do\n      NodeUp(i) -> i.name ++ \" up\"\n      NodeSuspect(i) -> i.name ++ \" suspect\"\n      NodeDead(i, why) -> i.name ++ \" dead: \" ++ why\n      NodeRejoined(i) -> i.name ++ \" rejoined\"\n    end\n  end\n\n  -- \u2500\u2500 the pure core \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- One peer's connection pair. `dialer` is the node_id that opened it; `cw`\n  -- is its control writer's pid (as an Int: opaque to the core); `creation`\n  -- the peer's creation, from its hello.\n  -- `binding` is the link's control-connection handshake transcript\n  -- (`NetKernel.link_binding`; empty in pure tests), which a CERT_UPDATE's\n  -- proof covers; `cu_sent`/`cu_seen` count the CERT_UPDATEs sent and the\n  -- newest taken on this link, so one is good on this link once only.\n  type CnLink = { node_id : String, gen : Int, cfd : Int, dfd : Int, dialer : String, cw : Int, creation : Int,\n                  binding : Bytes, cu_sent : Int, cu_seen : Int }\n\n  -- A half-assembled inbound pair: the control and data connections of one\n  -- peer arrive as two accepts, in either order (each is handshaked in its\n  -- own task). -1 for the half not yet here.\n  type CnHalf = { cfd : Int, dfd : Int, name : String, addr : String, creation : Int }\n\n  type CnState = {\n    cfg : CnConfig,\n    me : String,\n    driver : SwimDriver.State,\n    links : Map(String, CnLink),\n    halves : Map(String, CnHalf),\n    gen : Int,\n    dialing : Map(String, Int),          -- addr -> when an in-flight attempt is given up\n    backoff : Map(String, (Int, Int)),   -- addr -> (next try at, current delay)\n    pending : List(SwimDriver.Event),    -- folded into SWIM at the next tick\n    relays : Map(String, List(String)),  -- ping-req target -> requesters awaiting its ack\n    refused : List(String),              -- node_ids refused since the last tick\n    seed_ids : Map(String, String),      -- dialled seed \"host:port\" -> the node it reached\n    rejoining : List(String),            -- restarted nodes not yet seen Alive at their new creation\n    stopped : Bool,\n    reg : GlobalRegistry.Names,          -- the registry replica\n    regs : Map(String, (Int, Int)),      -- names registered HERE: name -> (pid, watcher pid)\n    vis : Map(String, GlobalPid.Pid),    -- the visible binding of every name, as last reported\n    certs : Map(String, NodeCert.Cert),  -- each certificate-mode peer's verified certificate\n    revs : List(NodeCert.SignedRevocation), -- every operator-signed revocation known here\n    cert_dead : Map(String, String),     -- peers dropped for their certificate -> why\n    rotated : Bool,                      -- this node's certificate was replaced since start\n    reg_swept_at : Int,                  -- when the registry's tombstones were last collected\n    remembered : Int,                    -- peer member views that held THIS node stale (`self_stale`)\n    reg_synced : Bool                    -- a peer's registry merged here, or no seeds to wait for\n  }\n\n  -- What a watcher of a name sees. `Lost` goes to watchers on the node that\n  -- held the name when a binding made HERE is superseded by another holder's.\n  type NameEvent = Bound(String, GlobalPid.Pid) | Unbound(String) | Lost(String, GlobalPid.Pid)\n\n  type RegisterError = Taken(GlobalPid.Pid) | Stopped\n\n  -- What the I/O layer must do after a core transition.\n  type CnEffect =\n      Send(String, List(Int))    -- a control frame to this node_id (dropped if no link)\n    | Dial(String)               -- open a pair to this \"host:port\"\n    | Install(CnLink)            -- a new link is current: start its readers\n    | Drop(CnLink, String)       -- shut this link's sockets and stop its writers; the\n                                 -- string is why, for the routes told of the close\n    | Discard(CnLink)            -- a pair never installed (a rejected duplicate): close it\n    | Emit(NodeEvent)            -- tell every subscriber\n    | Named(String, NameEvent)   -- tell every watcher of this name\n    | Unwatch(Int)               -- stop the Down-watcher with this pid\n\n  doc \"\"\"\n  The pure core's initial state for a node configured by [cfg]: a membership\n  holding only this node (Alive, incarnation 1), no links, an empty registry\n  replica, and those of `cfg.revocations` the operator signed (the rest are\n  dropped). [seed] seeds SWIM's probe-order randomness. Registry sync counts\n  as done at once when `cfg.seeds` is empty.\n  \"\"\"\n  fn core_new(cfg : CnConfig, seed : Int) : CnState do\n    let me = node_id_of(cfg.name)\n    let self_m = Membership.member(me, cfg.name, cfg.advertise, cfg.creation, Alive, 1)\n    let ms = Membership.observe(Membership.empty(), self_m)\n    { cfg: cfg, me: me, driver: SwimDriver.make(me, 1, ms, cfg.swim, cfg.period_ms, seed),\n      links: Map.empty(), halves: Map.empty(), gen: 0, dialing: Map.empty(), backoff: Map.empty(),\n      pending: Nil, relays: Map.empty(), refused: Nil, seed_ids: Map.empty(), rejoining: Nil, stopped: false,\n      reg: GlobalRegistry.empty(), regs: Map.empty(), vis: Map.empty(), certs: Map.empty(),\n      revs: List.filter(cfg.revocations, fn r -> Result.is_ok(check_revocation(cfg, r))), cert_dead: Map.empty(),\n      rotated: false, reg_swept_at: 0, remembered: 0, reg_synced: List.is_empty(cfg.seeds) }\n  end\n\n  -- \u2500\u2500 revocation and expiry \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- A peer's certificate is rechecked every tick: one that has expired, or\n  -- that a known revocation names, has its link dropped and the member\n  -- declared Dead with the reason (\"certificate expired\" / \"certificate\n  -- revoked\"), so subscribers see NodeDead(info, why) and sessions with it\n  -- are cancelled through the existing NodeDead path. Its handshakes are\n  -- refused from then on (NodeCert.Credentials.revoked reads this node's\n  -- list; expiry is checked in every handshake). Revocations travel as\n  -- REVOCATIONS control frames (tag 15): the whole list to every new link,\n  -- each new one to every linked peer. Only the operator's signature makes\n  -- one count, so a member cannot revoke another.\n\n  doc \"The REVOCATIONS control-frame tag, 15.\"\n  fn tag_revocations() : Int do 15 end\n\n  doc \"Encode [rs] as a REVOCATIONS control frame (msgpack `[15, [bin, ...]]`); the inverse of `decode_revocations`.\"\n  fn encode_revocations(rs : List(NodeCert.SignedRevocation)) : List(Int) do\n    Msgpack.encode(Msgpack.array([Msgpack.int(tag_revocations()),\n      Msgpack.array(List.map(rs, fn r -> Msgpack.bin(NodeCert.revocation_to_bytes(r))))]))\n  end\n\n  doc \"\"\"\n  The signed revocations in a REVOCATIONS [frame]. Lenient: an entry that\n  does not decode is skipped, and a frame that is not a REVOCATIONS frame\n  gives the empty list. Signatures are NOT checked here\n  (`check_revocation` does that).\n  \"\"\"\n  fn decode_revocations(frame : List(Int)) : List(NodeCert.SignedRevocation) do\n    match Msgpack.decode(frame) do\n      Ok(Msgpack.Array([Msgpack.Int(15), Msgpack.Array(bins)])) ->\n        List.filter_map(bins, fn b ->\n          match b do\n            Msgpack.Bin(bs) -> Result.to_option(NodeCert.revocation_from_bytes(bs))\n            _ -> None\n          end)\n      _ -> Nil\n    end\n  end\n\n  pfn operator_key(cfg : CnConfig) : Option(Bytes) do\n    match cfg.auth do\n      ClusterAuth.Certified(c) -> Some(c.operator_pubkey)\n      ClusterAuth.Secret(_) -> None\n    end\n  end\n\n  doc \"\"\"\n  Is [r] signed by this cluster's operator? `Ok(revocation)` when it\n  verifies against the operator key in `cfg.auth`, else `Err(why)`. Always\n  `Err` on a shared-secret node: it has no operator and accepts no\n  revocations.\n  \"\"\"\n  fn check_revocation(cfg : CnConfig, r : NodeCert.SignedRevocation) : Result(NodeCert.Revocation, String) do\n    match operator_key(cfg) do\n      None -> Err(\"this node runs in shared-secret mode; revocations need certificate mode\")\n      Some(op) -> NodeCert.verify_revocation(r, op)\n    end\n  end\n\n  doc \"The (verified) revocations the core knows, newest first.\"\n  fn core_revocations(st : CnState) : List(NodeCert.Revocation) do List.map(st.revs, fn r -> r.rev) end\n\n  doc \"\"\"\n  Add a revocation (from the API or a peer): kept and passed on to every\n  linked peer if it is the operator's and new here, ignored otherwise. The\n  certificates it names are dropped at the next tick.\n  \"\"\"\n  fn core_revoke(st : CnState, r : NodeCert.SignedRevocation) : (CnState, List(CnEffect)) do\n    let known = List.any(st.revs, fn k -> k.body == r.body)\n    if known || Result.is_err(check_revocation(st.cfg, r)) do (st, Nil)\n    else\n      let st1 = { st with revs: Cons(r, st.revs) }\n      let frame = encode_revocations(Cons(r, Nil))\n      let out = (st1, List.map(linked_ids(st1), fn id -> Send(id, frame)))\n      out\n    end\n  end\n\n  -- Why [c] no longer admits its node at [now_s], if it does not.\n  pfn cert_problem(st : CnState, c : NodeCert.Cert, now_s : Int) : Option(String) do\n    if NodeCert.is_revoked(c, core_revocations(st)) do Some(\"certificate revoked\")\n    else if NodeCert.expired(c, now_s) do Some(\"certificate expired\")\n    else None end end\n  end\n\n  doc \"\"\"\n  Recheck every linked peer's certificate at [now_s] (unix seconds): drop the\n  link of one that has expired or been revoked, and queue the member Dead\n  with that reason (the tick that follows reports it).\n  \"\"\"\n  fn core_check_certs(st : CnState, now_s : Int) : (CnState, List(CnEffect)) do\n    List.fold_left(Map.entries(st.links), (st, Nil), fn (acc, kv) ->\n      match (acc, kv) do\n        ((s, effs), (id, l)) ->\n          match Map.get(s.certs, id, Map.str_cmp) do\n            None -> (s, effs)\n            Some(c) ->\n              match cert_problem(s, c, now_s) do\n                None -> (s, effs)\n                Some(why) ->\n                  let s1 = queue({ s with links: Map.remove(s.links, id, Map.str_cmp),\n                                          certs: Map.remove(s.certs, id, Map.str_cmp),\n                                          cert_dead: Map.insert(s.cert_dead, id, why, Map.str_cmp) },\n                                 SwimDriver.PeerDown(id))\n                  (s1, Cons(Drop(l, why), effs))\n              end\n          end\n      end)\n  end\n\n  doc \"\"\"\n  Record [cert], the certificate peer [id] presented in its latest verified\n  handshake (certificate mode), replacing any earlier one; what `peer_cert`\n  answers and step 11b checks. `None` (shared-secret mode) leaves [st]\n  unchanged.\n  \"\"\"\n  fn core_peer_cert(st : CnState, id : String, cert : Option(NodeCert.Cert)) : CnState do\n    match cert do\n      Some(c) -> { st with certs: Map.insert(st.certs, id, c, Map.str_cmp) }\n      None -> st\n    end\n  end\n\n  -- \u2500\u2500 live certificate replacement (distributed-deploys step 12b) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- Issuance stays offline (D39): the operator (or CI) issues the new\n  -- certificate, and the node takes it while it runs (`replace_cert`, or a\n  -- changed MARCH_NODE_CERT file). New handshakes present it at once. A link\n  -- already up is NOT re-dialled -- a replaced link cancels every session on\n  -- it -- but re-authenticated in place: the node sends each linked peer a\n  -- CERT_UPDATE control frame (tag 16) with the new certificate and a proof,\n  -- an ed25519 signature by the NEW certificate's key over (sender, receiver,\n  -- the link's handshake transcript, a per-link counter, certificate). The\n  -- frame rides the link's MAC, so only the peer that did the link's\n  -- handshake can send it, and the binding keeps it good on that link\n  -- only, once (see below); the proof shows that peer holds the\n  -- new key, so a certificate for a new key (a rotation after a key leak)\n  -- is as safe to take in place as a renewal of the same key. The receiver\n  -- checks it as a handshake would -- operator's signature, not expired, not\n  -- revoked, and naming the same node -- and that it is not issued before\n  -- the certificate it replaces, and then holds it for that link:\n  -- the per-tick expiry recheck, `peer_cert` and the raw-send and role\n  -- checks all read the new one, so the link outlives the old certificate.\n  -- A refused update changes nothing (the old certificate expires as it\n  -- would have). A link formed after a replacement is sent one too, in case\n  -- its handshake began before it. A peer that predates CERT_UPDATE ignores\n  -- the frame and drops the link when the old certificate expires; the\n  -- redial then handshakes under the new one (sessions on it are lost).\n\n  doc \"The CERT_UPDATE control-frame tag, 16.\"\n  fn tag_cert_update() : Int do 16 end\n\n  -- The proof is bound to the LINK (security review, dd step 12b): it also\n  -- covers the link's control-connection handshake transcript (both\n  -- hellos, so both nonces and both ephemeral keys: no two links share one)\n  -- and a counter the sender raises on every update it sends on that link.\n  -- The receiver takes an update only on the link it was made for, and only\n  -- with a counter above the last it took there, so a frame recorded on one\n  -- link (frames are MAC'd, not encrypted) is refused on any other, and one\n  -- recorded earlier on the same link is refused there too. Without the\n  -- binding, a holder of a leaked OLD key could handshake under the old\n  -- certificate and replay the node's recorded update to the new one, and\n  -- the old certificate's revocation would no longer drop that link.\n  -- The v1 frame ([16, cert, proof], no binding) is refused: a peer that\n  -- predates the binding falls back to the redial at the old certificate's\n  -- expiry, as one that predates CERT_UPDATE does.\n\n  doc \"\"\"\n  What a CERT_UPDATE's proof signs: the sender, the receiver, the link's\n  handshake transcript [binding], the update's [counter] on that link, and\n  the certificate's wire bytes.\n  \"\"\"\n  fn cert_update_message(signed : NodeCert.Signed, from_id : String, to_id : String, binding : Bytes, counter : Int) : Bytes do\n    Bytes.concat(Bytes.concat(Bytes.from_string(\"march-cert-update-v2 \" ++ from_id ++ \" \" ++ to_id ++ \" \" ++ int_to_string(counter) ++ \" \"),\n                              Bytes.from_string(Bytes.to_hex(binding) ++ \" \")),\n                 Bytes.from_list(NodeCert.to_bytes(signed)))\n  end\n\n  doc \"\"\"\n  Encode a v2 CERT_UPDATE frame (msgpack `[16, \"v2\", counter, cert, proof]`)\n  from an already-made [proof]; `sign_cert_update` makes the proof and calls\n  this. The inverse of `decode_cert_update`.\n  \"\"\"\n  fn encode_cert_update(signed : NodeCert.Signed, counter : Int, proof : Bytes) : List(Int) do\n    Msgpack.encode(Msgpack.array([Msgpack.int(tag_cert_update()), Msgpack.str(\"v2\"), Msgpack.int(counter),\n                                  Msgpack.bin(NodeCert.to_bytes(signed)), Msgpack.bin(Bytes.to_list(proof))]))\n  end\n\n  doc \"A CERT_UPDATE frame's certificate, counter and proof.\"\n  fn decode_cert_update(frame : List(Int)) : Result((NodeCert.Signed, Int, Bytes), String) do\n    match Msgpack.decode(frame) do\n      Ok(Msgpack.Array([Msgpack.Int(16), Msgpack.Str(v), Msgpack.Int(n), Msgpack.Bin(cb), Msgpack.Bin(pb)])) ->\n        if v != \"v2\" do Err(\"malformed CERT_UPDATE frame\")\n        else\n          match NodeCert.from_bytes(cb) do\n            Err(e) -> Err(e)\n            Ok(signed) -> Ok((signed, n, Bytes.from_list(pb)))\n          end\n        end\n      Ok(Msgpack.Array(items)) ->\n        if List.length(items) == 3 do Err(\"a CERT_UPDATE not bound to this link (v1): refused\")\n        else Err(\"malformed CERT_UPDATE frame\") end\n      _ -> Err(\"malformed CERT_UPDATE frame\")\n    end\n  end\n\n  doc \"\"\"\n  The CERT_UPDATE frame node [from_id] sends [to_id] on the link whose\n  handshake transcript is [binding], as its [counter]th update there:\n  [signed], with a proof by its key [sk].\n  \"\"\"\n  fn sign_cert_update(signed : NodeCert.Signed, sk : Bytes, from_id : String, to_id : String,\n                      binding : Bytes, counter : Int) : List(Int) do\n    encode_cert_update(signed, counter, ed25519_sign(sk, cert_update_message(signed, from_id, to_id, binding, counter)))\n  end\n\n  pfn cert_update_on(l : CnLink, creds : NodeCert.Credentials, me : String, counter : Int) : List(Int) do\n    sign_cert_update(creds.signed, creds.secret_key, me, l.node_id, l.binding, counter)\n  end\n\n  doc \"\"\"\n  This node's certificate is replaced by [signed], whose key is [sk] (both\n  already checked: `replace_cert`). Dials handshake with it from now on, and\n  every linked peer is sent a CERT_UPDATE. A shared-secret node is unchanged.\n  \"\"\"\n  fn core_replace_cert(st : CnState, signed : NodeCert.Signed, sk : Bytes) : (CnState, List(CnEffect)) do\n    match st.cfg.auth do\n      ClusterAuth.Secret(_) -> (st, Nil)\n      ClusterAuth.Certified(cr) ->\n        let creds = { cr with signed: signed, secret_key: sk }\n        let st1 = { st with cfg: { st.cfg with auth: ClusterAuth.Certified(creds) }, rotated: true }\n        send_cert_updates(st1, creds)\n    end\n  end\n\n  pfn put_link(st : CnState, l : CnLink) : CnState do\n    { st with links: Map.insert(st.links, l.node_id, l, Map.str_cmp) }\n  end\n\n  -- Send every linked peer the next CERT_UPDATE on its link.\n  pfn send_cert_updates(st : CnState, creds : NodeCert.Credentials) : (CnState, List(CnEffect)) do\n    List.fold_left(Map.entries(st.links), (st, Nil), fn (acc, kv) ->\n      match (acc, kv) do\n        ((s, effs), (id, l)) ->\n          let n = l.cu_sent + 1\n          let frame = cert_update_on(l, creds, s.me, n)\n          (put_link(s, { l with cu_sent: n }), Cons(Send(id, frame), effs))\n      end)\n  end\n\n  doc \"\"\"\n  A CERT_UPDATE from linked peer [from], at [now_s] (unix seconds): the\n  certificate must verify under the operator key, be unexpired and not\n  revoked, name the same node as the one [from] presented before, not be\n  issued before it (`NodeCert.supersedes`), and come with a proof by its own\n  key for this sender and receiver, THIS link's handshake transcript and a\n  counter above the last update taken on this link. Ok with the new state\n  (holding it as [from]'s certificate) and the certificate, or Err with why\n  it was refused.\n  \"\"\"\n  fn core_peer_cert_update(st : CnState, from : String, frame : List(Int), now_s : Int)\n      : Result((CnState, NodeCert.Cert), String) do\n    match (operator_key(st.cfg), Map.get(st.certs, from, Map.str_cmp), Map.get(st.links, from, Map.str_cmp)) do\n      (None, _, _) -> Err(\"this node runs in shared-secret mode\")\n      (_, None, _) -> Err(\"no certificate on record for this peer\")\n      (_, _, None) -> Err(\"no link to this peer\")\n      (Some(op), Some(old), Some(l)) ->\n        match decode_cert_update(frame) do\n          Err(e) -> Err(e)\n          Ok((signed, counter, proof)) ->\n            match NodeCert.verify(signed, op, now_s) do\n              Err(e) -> Err(e)\n              Ok(c) ->\n                if NodeCert.is_revoked(c, core_revocations(st)) do Err(\"certificate revoked\")\n                else if NodeCert.node_name(c.node) != NodeCert.node_name(old.node) do\n                  Err(\"the new certificate names \" ++ c.node ++ \", not \" ++ old.node)\n                else\n                  match (NodeCert.order_problem(c, old), NodeCert.key_from_hex(c.pubkey, 32)) do\n                    (Some(why), _) -> Err(why)\n                    (_, Err(e)) -> Err(e)\n                    (None, Ok(pk)) ->\n                      if not(ed25519_verify(pk, cert_update_message(signed, from, st.me, l.binding, counter), proof)) do\n                        Err(\"the proof is not by the new certificate's key for this link\")\n                      else if counter <= l.cu_seen do\n                        Err(\"a CERT_UPDATE already taken on this link (counter \" ++ int_to_string(counter) ++ \"): refused\")\n                      else\n                        let st1 = put_link({ st with certs: Map.insert(st.certs, from, c, Map.str_cmp) }, { l with cu_seen: counter })\n                        let out = Ok((st1, c))\n                        out\n                      end end\n                  end\n                end end\n            end\n        end\n    end\n  end\n\n  doc \"Every member in the core's SWIM view, in any status, this node included.\"\n  fn core_members(st : CnState) : List(Member) do Membership.members(st.driver.swim.members) end\n\n  doc \"The core's membership entry for node [id], or None if it has never heard of it.\"\n  fn core_member(st : CnState, id : String) : Option(Member) do Membership.get(st.driver.swim.members, id) end\n\n  pfn linked_ids(st : CnState) : List(String) do Map.keys(st.links) end\n\n  pfn is_linked(st : CnState, id : String) : Bool do Map.contains_key(st.links, id, Map.str_cmp) end\n\n  pfn queue(st : CnState, ev : SwimDriver.Event) : CnState do\n    { st with pending: Cons(ev, st.pending) }\n  end\n\n  -- \u2500\u2500 events: what changed between two member views \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- [dead_cause] names why a node that went Dead in this step did.\n  -- [rejoining]: nodes whose new creation first appeared NOT Alive (a\n  -- duplicate pair shut by the peer just as it was installed reads as a lost\n  -- connection, so the restarted node is Suspect at its new creation until it\n  -- refutes), or that left Dead for Suspect (the same close during a\n  -- partition heal); their first Alive is reported as the rejoin it is, not\n  -- as `up`.\n  pfn member_events(before : Members, after : Members, me : String, dead_cause : String -> String,\n                    rejoining : List(String)) : List(NodeEvent) do\n    List.flat_map(Membership.members(after), fn m ->\n      if m.node_id == me do\n        Nil\n      else\n        match Membership.get(before, m.node_id) do\n          None ->\n            match m.status do\n              Alive -> Cons(NodeUp(info_of(m)), Nil)\n              _ -> Nil\n            end\n          Some(o) ->\n            if o.creation != m.creation do\n              let gone = match o.status do\n                Dead -> Nil\n                _ -> Cons(NodeDead(info_of(o), \"restarted as creation \" ++ int_to_string(m.creation)), Nil)\n              end\n              let now_ev = match m.status do\n                Alive -> Cons(NodeRejoined(info_of(m)), Nil)\n                _ -> Nil\n              end\n              List.append(gone, now_ev)\n            else\n              match (o.status, m.status) do\n                (Alive, Suspect) -> Cons(NodeSuspect(info_of(m)), Nil)\n                (Alive, Dead) -> Cons(NodeDead(info_of(m), dead_cause(m.node_id)), Nil)\n                (Suspect, Dead) -> Cons(NodeDead(info_of(m), dead_cause(m.node_id)), Nil)\n                (Suspect, Alive) ->\n                  if List.member(rejoining, m.node_id) do Cons(NodeRejoined(info_of(m)), Nil)\n                  else Cons(NodeUp(info_of(m)), Nil) end\n                (Dead, Alive) -> Cons(NodeRejoined(info_of(m)), Nil)\n                _ -> Nil\n              end\n            end\n        end\n      end)\n  end\n\n  -- The rejoin set after a step: add a node whose creation changed to a\n  -- non-Alive status, or that was Dead and is not Alive yet (a heal whose\n  -- new link's Alive and a closed duplicate pair's Suspect landed in one\n  -- step reads as Dead -> Suspect); drop one that is Alive now (its rejoin\n  -- was reported).\n  pfn next_rejoining(before : Members, after : Members, rejoining : List(String)) : List(String) do\n    List.filter_map(Membership.members(after), fn m ->\n      let was = match Membership.get(before, m.node_id) do\n        Some(o) ->\n          let was_dead = match o.status do\n            Dead -> true\n            _ -> false\n          end\n          o.creation != m.creation || was_dead\n        None -> false\n      end\n      let alive = match m.status do\n        Alive -> true\n        _ -> false\n      end\n      if alive do None\n      else if was || List.member(rejoining, m.node_id) do Some(m.node_id)\n      else None end end)\n  end\n\n  -- The effects of a set of events: emit each, and drop the links of every\n  -- node that just went Dead (the edge, not the level: a node still Dead\n  -- after a heal redial keeps its fresh link until it refutes).\n  pfn event_effects(st : CnState, evs : List(NodeEvent)) : (CnState, List(CnEffect)) do\n    event_effects_acc(st, evs, Nil)\n  end\n\n  -- Plain recursion, not a fold with a lambda: the lambda form made the\n  -- compiled backend emit a call to an undefined global named after a\n  -- let-binding inside it (see the progress record).\n  pfn event_effects_acc(st : CnState, evs : List(NodeEvent), acc : List(CnEffect)) : (CnState, List(CnEffect)) do\n    match evs do\n      Nil -> (st, List.reverse(acc))\n      Cons(ev, rest) ->\n        match ev do\n          NodeDead(i, _) ->\n            match Map.get(st.links, i.node_id, Map.str_cmp) do\n              Some(l) ->\n                let without = { st with links: Map.remove(st.links, i.node_id, Map.str_cmp) }\n                let why = \"node \" ++ i.name ++ \" dead: \" ++ (match ev do NodeDead(_, w) -> w | _ -> \"\" end)\n                event_effects_acc(without, rest, Cons(Emit(ev), Cons(Drop(l, why), acc)))\n              None -> event_effects_acc(st, rest, Cons(Emit(ev), acc))\n            end\n          _ -> event_effects_acc(st, rest, Cons(Emit(ev), acc))\n        end\n    end\n  end\n\n  -- \u2500\u2500 ticks \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- The member whose advertised address is [addr], if any.\n  pfn member_at(st : CnState, addr : String) : Option(Member) do\n    List.find(core_members(st), fn m -> m.addr == addr && m.node_id != st.me)\n  end\n\n  -- Every address worth a dial right now: members with a known address and\n  -- no link (Alive ones from gossip: the full mesh; Suspect and Dead ones:\n  -- the heal path), and seeds no linked member advertises. Never ourselves,\n  -- never an address with an attempt in flight or still backing off.\n  pfn dial_targets(st : CnState, now : Int) : List(String) do\n    let from_members = List.filter_map(core_members(st), fn m ->\n      if m.node_id == st.me || String.is_empty(m.addr) || is_linked(st, m.node_id) do None else Some(m.addr) end)\n    let linked_addrs = List.filter_map(core_members(st), fn m ->\n      if is_linked(st, m.node_id) do Some(m.addr) else None end)\n    -- A seed is satisfied when a linked member advertises it, or when a dial\n    -- of it reached a node that is linked or is us: a seed can be spelled\n    -- differently from the address its node advertises (a hostname, another\n    -- interface), and redialling it would replace the live pair every time.\n    let from_seeds = List.filter(st.cfg.seeds, fn a ->\n      not(List.member(linked_addrs, a)) && not(seed_reached(st, a)))\n    let all = List.dedup(List.append(from_members, from_seeds))\n    List.filter(all, fn a ->\n      a != st.cfg.advertise &&\n      not(Map.contains_key(st.dialing, a, Map.str_cmp)) &&\n      (match Map.get(st.backoff, a, Map.str_cmp) do\n         None -> true\n         Some((at, _)) -> at <= now\n       end))\n  end\n\n  pfn seed_reached(st : CnState, a : String) : Bool do\n    match Map.get(st.seed_ids, a, Map.str_cmp) do\n      Some(id) -> id == st.me || is_linked(st, id)\n      None -> false\n    end\n  end\n\n  -- Forget attempts past their deadline (a dial task that is still parked\n  -- in a connect will report later; a late success is still a link).\n  pfn expire_dials(st : CnState, now : Int) : CnState do\n    let live = Map.filter(st.dialing, fn _a -> fn until -> until > now, Map.str_cmp)\n    { st with dialing: live }\n  end\n\n  pfn plan_dials(st : CnState, now : Int) : (CnState, List(CnEffect)) do\n    let st1 = expire_dials(st, now)\n    let targets = dial_targets(st1, now)\n    let until = now + st1.cfg.dial_timeout_ms * 2 + st1.cfg.handshake_timeout_ms * 2\n    let dialing = List.fold_left(targets, st1.dialing, fn (m, a) -> Map.insert(m, a, until, Map.str_cmp))\n    let out = ({ st1 with dialing: dialing }, List.map(targets, fn a -> Dial(a)))\n    out\n  end\n\n  pfn swim_frames(st : CnState, acts : List(Swim.Action)) : List(CnEffect) do\n    let ids = linked_ids(st)\n    List.flat_map(acts, fn a ->\n      List.map(SwimDriver.action_frames(a, st.me, ids), fn pair ->\n        match pair do (dest, bytes) -> Send(dest, bytes) end))\n  end\n\n  -- Expire the registry's tombstones (GlobalRegistry.collect_tombstones), at\n  -- most once a minute and at least four times per grace period: each pass\n  -- walks the whole registry, and a tombstone outlives its grace by at most\n  -- one interval.\n  pfn collect_tombstones(st : CnState, now : Int) : CnState do\n    let grace = st.cfg.tombstone_grace_ms\n    let every = if grace / 4 < 60000 do (if grace / 4 < 1 do 1 else grace / 4 end) else 60000 end\n    if now - st.reg_swept_at < every do st\n    else { st with reg: GlobalRegistry.collect_tombstones(st.reg, now, grace), reg_swept_at: now }\n    end\n  end\n\n  doc \"\"\"\n  One tick at [now] (unix ms): recheck peers' certificates (dropping expired\n  or revoked ones), fold the queued SWIM events and step the driver (its\n  actions become control frames to linked peers), derive the member events,\n  plan the dials this tick allows, collect expired registry tombstones, send\n  an anti-entropy REGISTRY_SYNC_REQ to the peers due one, and report changes\n  to visible name bindings. Returns the new state and the effects to perform.\n  \"\"\"\n  fn core_tick(st0 : CnState, now : Int) : (CnState, List(CnEffect)) do\n    let (st, cert_effs) = core_check_certs(st0, now / 1000)\n    let before = st.driver.swim.members\n    let timed_out = List.filter_map(Map.entries(st.driver.swim.suspect_deadlines), fn kv ->\n      match kv do (id, dl) -> if dl <= now do Some(id) else None end end)\n    let refused = st.refused\n    let evs_in = List.reverse(st.pending)\n    match SwimDriver.step(st.driver, now, evs_in) do\n      (d2, acts) ->\n        let st2 = { st with driver: d2, pending: Nil, refused: Nil }\n        let frames = swim_frames(st2, acts)\n        let cert_dead = st.cert_dead\n        let cause = fn id ->\n          match Map.get(cert_dead, id, Map.str_cmp) do\n            Some(why) -> why\n            None ->\n          if List.member(refused, id) do \"connection refused\"\n          else if List.member(timed_out, id) do \"suspect timeout\"\n          else \"gossip\" end end\n          end\n        let evs = member_events(before, d2.swim.members, st.me, cause, st.rejoining)\n        let rejoining = next_rejoining(before, d2.swim.members, st.rejoining)\n        match event_effects({ st2 with rejoining: rejoining }, evs) do\n          (st3, ev_effs) ->\n            match plan_dials(st3, now) do\n              (st4, dials) ->\n                let swept = collect_tombstones(st4, now)\n                let ae_peers = List.filter(SwimDriver.anti_entropy_peers(swept.driver, now), fn id -> is_linked(swept, id))\n                let st5 = if List.is_empty(ae_peers) do swept else { swept with driver: SwimDriver.bump_anti_entropy(swept.driver, now) } end\n                -- The root hash hashes every entry: only when a REQ goes out.\n                let ae = if List.is_empty(ae_peers) do Nil else\n                  let req = NetKernel.encode_registry_sync_req(GlobalRegistry.root_hash(st5.reg))\n                  List.map(ae_peers, fn id -> Send(id, req))\n                end\n                match refresh_names(st5) do\n                  (st6, name_effs) ->\n                    let out = (st6, List.append(cert_effs, List.append(frames, List.append(ev_effs, List.append(dials, List.append(ae, name_effs))))))\n                    out\n                end\n            end\n        end\n    end\n  end\n\n  -- \u2500\u2500 links \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- The pair two nodes both keep when each dialled the other: the one\n  -- dialled by the lower node_id.\n  -- A pair from a newer creation of the peer always wins: the old one is to\n  -- a process that is gone, even if no RST has told us yet.\n  pfn keeps_new(st : CnState, old : CnLink, new_l : CnLink) : Bool do\n    if new_l.creation != old.creation do\n      new_l.creation > old.creation\n    else if old.dialer == new_l.dialer do\n      true\n    else\n      let lower = if st.me < new_l.node_id do st.me else new_l.node_id end\n      new_l.dialer == lower\n    end end\n  end\n\n  doc \"\"\"\n  A pair to [id] is up ([cfd]/[dfd], opened by [dialer], its control writer\n  [cw]). Applies the duplicate rule, gives it a generation, records what the\n  handshake said about the peer (name, advertised address, creation) as an\n  Alive observation. A completed authenticated link directly proves a peer\n  previously declared Dead or Suspect is alive, so its observation advances\n  that peer's incarnation; otherwise a split brain can leave both sides\n  retaining Dead records that neither can independently refute. It then sends\n  our whole member view.\n  \"\"\"\n  fn core_linked(st : CnState, id : String, name : String, addr : String, creation : Int,\n                 cfd : Int, dfd : Int, dialer : String, cw : Int) : (CnState, List(CnEffect)) do\n    core_linked_bound(st, id, name, addr, creation, cfd, dfd, dialer, cw, Bytes.empty())\n  end\n\n  doc \"`core_linked`, for a link whose control-connection handshake transcript is [binding] (`NetKernel.link_binding`).\"\n  fn core_linked_bound(st : CnState, id : String, name : String, addr : String, creation : Int,\n                       cfd : Int, dfd : Int, dialer : String, cw : Int, binding : Bytes) : (CnState, List(CnEffect)) do\n    let gen = st.gen + 1\n    let l = { node_id: id, gen: gen, cfd: cfd, dfd: dfd, dialer: dialer, cw: cw, creation: creation,\n              binding: binding, cu_sent: 0, cu_seen: 0 }\n    let st1 = { st with gen: gen }\n    let (st2, drops) = match Map.get(st1.links, id, Map.str_cmp) do\n      None -> (st1, Nil)\n      Some(old) ->\n        if keeps_new(st1, old, l) do\n          (st1, Cons(Drop(old, \"replaced\"), Nil))\n        else\n          (st1, Cons(Discard(l), Nil))\n        end\n    end\n    let kept_new = match drops do\n      Cons(Discard(_), Nil) -> false\n      _ -> true\n    end\n    if kept_new do\n      let known_incarnation = match core_member(st2, id) do\n        Some(m) ->\n          if m.creation == creation do\n            match m.status do\n              Alive -> m.incarnation\n              _ -> m.incarnation + 1\n            end\n          else 0 end\n        None -> 0\n      end\n      let obs = Membership.member(id, name, addr, creation, Alive, known_incarnation)\n      -- After a replacement the handshake may have begun under the old\n      -- certificate: tell the peer the current one (the link's first\n      -- CERT_UPDATE).\n      let (l2, certsync) = match st2.cfg.auth do\n        ClusterAuth.Certified(cr) ->\n          if st2.rotated do ({ l with cu_sent: 1 }, Cons(Send(id, cert_update_on(l, cr, st2.me, 1)), Nil)) else (l, Nil) end\n        ClusterAuth.Secret(_) -> (l, Nil)\n      end\n      let st3 = queue({ st2 with links: Map.insert(st2.links, id, l2, Map.str_cmp),\n                                 cert_dead: Map.remove(st2.cert_dead, id, Map.str_cmp),\n                                 backoff: Map.remove(st2.backoff, addr, Map.str_cmp),\n                                 dialing: Map.remove(st2.dialing, addr, Map.str_cmp) },\n                      SwimDriver.GossipFrame(obs))\n      let sync = SwimDriver.encode_members_sync(List.append(core_members(st3), Cons(obs, Nil)))\n      let regsync = NetKernel.encode_registry_sync_resp(GlobalRegistry.root_hash(st3.reg), GlobalRegistry.all_entries(st3.reg))\n      let revsync = if List.is_empty(st3.revs) do Nil else Cons(Send(id, encode_revocations(st3.revs)), Nil) end\n      let out = (st3, List.append(drops, Cons(Install(l2), Cons(Send(id, sync), Cons(Send(id, regsync), List.append(revsync, certsync))))))\n      out\n    else\n      (st2, drops)\n    end\n  end\n\n  doc \"\"\"\n  A pair WE dialled to [dialed] (\"host:port\" as dialled -- a seed may be\n  spelled differently from the peer's advertised [peer_addr]) is up: record\n  which node that address reaches, clear its dial state, and link it.\n  \"\"\"\n  fn core_dialed(st : CnState, dialed : String, id : String, name : String, peer_addr : String,\n                 creation : Int, cfd : Int, dfd : Int, cw : Int) : (CnState, List(CnEffect)) do\n    core_dialed_bound(st, dialed, id, name, peer_addr, creation, cfd, dfd, cw, Bytes.empty())\n  end\n\n  doc \"`core_dialed`, for a link whose control-connection handshake transcript is [binding] (`NetKernel.link_binding`).\"\n  fn core_dialed_bound(st : CnState, dialed : String, id : String, name : String, peer_addr : String,\n                       creation : Int, cfd : Int, dfd : Int, cw : Int, binding : Bytes) : (CnState, List(CnEffect)) do\n    let a = if String.is_empty(peer_addr) do dialed else peer_addr end\n    let st1 = { st with seed_ids: Map.insert(st.seed_ids, dialed, id, Map.str_cmp),\n                        dialing: Map.remove(st.dialing, dialed, Map.str_cmp),\n                        backoff: Map.remove(st.backoff, dialed, Map.str_cmp) }\n    core_linked_bound(st1, id, name, a, creation, cfd, dfd, st1.me, cw, binding)\n  end\n\n  doc \"A dial of [addr] reached this node itself (a seed list naming us): never dial it again.\"\n  fn core_seed_self(st : CnState, addr : String) : CnState do\n    { st with seed_ids: Map.insert(st.seed_ids, addr, st.me, Map.str_cmp),\n              dialing: Map.remove(st.dialing, addr, Map.str_cmp) }\n  end\n\n  doc \"\"\"\n  A connection of the current pair to [id], generation [gen], ended. A close\n  from a replaced generation is ignored. Otherwise the link is gone, the\n  member is suspected (a hint, not a verdict) and redialled at once.\n  \"\"\"\n  fn core_link_closed(st : CnState, id : String, gen : Int) : (CnState, List(CnEffect)) do\n    match Map.get(st.links, id, Map.str_cmp) do\n      None -> (st, Nil)\n      Some(l) ->\n        if l.gen != gen do\n          (st, Nil)\n        else\n          let st1 = { st with links: Map.remove(st.links, id, Map.str_cmp) }\n          let addr = match core_member(st1, id) do\n            Some(m) -> m.addr\n            None -> \"\"\n          end\n          let st2 = { st1 with backoff: Map.remove(st1.backoff, addr, Map.str_cmp) }\n          let out = (queue(st2, SwimDriver.ConnLost(id)), Cons(Drop(l, \"connection lost\"), Nil))\n          out\n        end\n    end\n  end\n\n  doc \"\"\"\n  A dial to [addr] failed. [refused]: nothing listens there -- for a member\n  we know at that address that is not already Dead, that is definite\n  (PeerDown: Dead at the next tick, cause \"connection refused\"). Either way\n  the address backs off, doubling to redial_max_ms.\n  \"\"\"\n  fn core_dial_failed(st : CnState, now : Int, addr : String, refused : Bool) : CnState do\n    let delay = match Map.get(st.backoff, addr, Map.str_cmp) do\n      None -> st.cfg.redial_min_ms\n      Some((_, d)) -> if d * 2 > st.cfg.redial_max_ms do st.cfg.redial_max_ms else d * 2 end\n    end\n    let st1 = { st with dialing: Map.remove(st.dialing, addr, Map.str_cmp),\n                        backoff: Map.insert(st.backoff, addr, (now + delay, delay), Map.str_cmp) }\n    if refused do\n      match member_at(st1, addr) do\n        Some(m) ->\n          match m.status do\n            Dead -> st1\n            _ -> queue({ st1 with refused: Cons(m.node_id, st1.refused) }, SwimDriver.PeerDown(m.node_id))\n          end\n        None -> st1\n      end\n    else\n      st1\n    end\n  end\n\n  -- \u2500\u2500 control frames \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn relay_ack(st : CnState, target : String) : (CnState, List(CnEffect)) do\n    match Map.get(st.relays, target, Map.str_cmp) do\n      None -> (st, Nil)\n      Some(reqs) ->\n        let ack = SwimDriver.encode_msg(SwimDriver.SwimPingAck(target))\n        let out = ({ st with relays: Map.remove(st.relays, target, Map.str_cmp) },\n                   List.map(reqs, fn r -> Send(r, ack)))\n        out\n    end\n  end\n\n  doc \"\"\"\n  A control frame from [from] (tag [tag]). SWIM pings are answered at once;\n  acks, gossip and member syncs are queued for the next tick; a ping-req is\n  relayed (we ping the target, and pass its ack back to the requester).\n  Frames of other families are ignored here (the registry and the data\n  plane handle theirs).\n  \"\"\"\n  fn core_frame(st : CnState, from : String, tag : Int, frame : List(Int)) : (CnState, List(CnEffect)) do\n    if tag == 13 do\n      match SwimDriver.decode_member_gossip(frame) do\n        Ok(m) -> (queue(st, SwimDriver.GossipFrame(m)), Nil)\n        Err(_) -> (st, Nil)\n      end\n    else if tag == 14 do\n      match SwimDriver.decode_members_sync(frame) do\n        Ok(ms) ->\n          let st1 = if List.any(ms, fn m -> self_stale(st, m)) do { st with remembered: st.remembered + 1 } else st end\n          (List.fold_left(ms, st1, fn (s, m) -> queue(s, SwimDriver.GossipFrame(m))), Nil)\n        Err(_) -> (st, Nil)\n      end\n    else if tag == 5 || tag == 6 do\n      registry_frame(st, from, tag, frame)\n    else if tag == tag_revocations() do\n      List.fold_left(decode_revocations(frame), (st, Nil), fn (acc, r) ->\n        match acc do\n          (s, effs) ->\n            match core_revoke(s, r) do\n              (s2, e2) -> (s2, List.append(effs, e2))\n            end\n        end)\n    else if tag >= 0 && tag <= 3 do\n      match SwimDriver.decode_msg(frame) do\n        Err(_) -> (st, Nil)\n        Ok(msg) ->\n          match msg do\n            SwimDriver.SwimPing(_) ->\n              (st, Cons(Send(from, SwimDriver.encode_msg(SwimDriver.SwimPingAck(st.me))), Nil))\n            SwimDriver.SwimPingAck(sender) ->\n              relay_ack(queue(st, SwimDriver.PingAck(sender)), sender)\n            SwimDriver.SwimPingReq(requester, target) ->\n              if is_linked(st, target) do\n                let reqs = match Map.get(st.relays, target, Map.str_cmp) do\n                  None -> Cons(requester, Nil)\n                  Some(rs) -> Cons(requester, rs)\n                end\n                ({ st with relays: Map.insert(st.relays, target, reqs, Map.str_cmp) },\n                 Cons(Send(target, SwimDriver.encode_msg(SwimDriver.SwimPing(st.me))), Nil))\n              else\n                (st, Nil)\n              end\n            _ ->\n              match SwimDriver.msg_to_event(msg) do\n                Some(ev) -> (queue(st, ev), Nil)\n                None -> (st, Nil)\n              end\n          end\n      end\n    else\n      (st, Nil)\n    end end end end end\n  end\n\n  -- Does [m], from a peer's member view (the MEMBERS_SYNC a peer sends when a\n  -- link comes up), show THIS node as the peer last knew it before a\n  -- restart (an earlier creation) or as Dead at this creation (a restart\n  -- that kept its creation, or a heal after the peer declared us dead)?\n  -- Either way that peer reports our coming back as `NodeRejoined` and\n  -- treats us as settling (Topology), so we mirror it (`rejoined_at`).\n  pfn self_stale(st : CnState, m : Member) : Bool do\n    if m.node_id != st.me || m.creation <= 0 do false\n    else if m.creation < st.cfg.creation do true\n    else if m.creation == st.cfg.creation do\n      match m.status do\n        Dead -> true\n        _ -> false\n      end\n    else false end end end\n  end\n\n  doc \"How many peer member views have shown this node as rejoining (`self_stale`); for tests of the core.\"\n  fn core_remembered(st : CnState) : Int do st.remembered end\n\n  doc \"Has a peer's registry been merged here (or did this node start with no seeds to wait for)? For tests of the core.\"\n  fn core_reg_synced(st : CnState) : Bool do st.reg_synced end\n\n  -- \u2500\u2500 names \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  The visible binding of [name] as last computed by the core (hidden\n  bindings, whose holder is Dead or restarted, give None); the pure\n  counterpart of `lookup`.\n  \"\"\"\n  fn core_lookup(st : CnState, name : String) : Option(GlobalPid.Pid) do\n    Map.get(st.vis, name, Map.str_cmp)\n  end\n\n  -- Is binding [e] visible here: held by a node that is not Dead in our view\n  -- and has not restarted since it registered? A holder we have not heard of\n  -- yet is visible (the binding came from someone who has).\n  pfn visible(st : CnState, e : GlobalRegistry.Entry) : Bool do\n    if not(e.present) do false\n    else if e.node_id == st.me do e.creation == st.cfg.creation\n    else\n      match core_member(st, e.node_id) do\n        None -> true\n        Some(m) ->\n          let live = match m.status do\n            Dead -> false\n            _ -> true\n          end\n          live && m.creation == e.creation\n      end\n    end end\n  end\n\n  -- \u2500\u2500 cross-node references (distributed-deploys step 11b) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- Cross-node references are handed out, not computed (plan section 1). In\n  -- CERTIFICATE mode `lookup` (and `names`) hides a binding unless a raw\n  -- send to its holder would be allowed (`raw_allowed`: both this node's\n  -- certificate and the holder's verified one carry raw_send; this node's\n  -- own bindings always show): a name you cannot raw-send to is not a\n  -- reference you should hold. A holder this node has not verified (no link\n  -- yet) is hidden until it is. The stdlib's coordination namespaces are\n  -- exempt (`reference_exempt`): access-point offers (\"ap:\"), session\n  -- endpoints (\"session:\") and topology markers (\"topo:\") are found by name\n  -- whatever the holder's flags, and are checked by role where they are\n  -- used (SessionNode). A send to any binding still goes through raw-send\n  -- denial. `GlobalPid.make` stays pure: a pid built by hand is only a\n  -- value, and sending to it is what is checked.\n\n  doc \"The registry name prefixes exempt from certificate-mode hiding: SessionNode's and Topology's coordination names.\"\n  fn reference_namespaces() : List(String) do [\"ap:\", \"session:\", \"topo:\"] end\n\n  doc \"Is [name] in a namespace `lookup` never hides (`reference_namespaces()`)?\"\n  fn reference_exempt(name : String) : Bool do\n    List.any(reference_namespaces(), fn p -> String.starts_with(name, p))\n  end\n\n  -- This node's certificate, or None in shared-secret mode.\n  pfn core_own_cert(st : CnState) : Option(NodeCert.Cert) do\n    match st.cfg.auth do\n      ClusterAuth.Certified(cr) -> Some(cr.signed.cert)\n      ClusterAuth.Secret(_) -> None\n    end\n  end\n\n  -- May this node hold binding [name] -> [e] as a reference?\n  pfn reference_visible(st : CnState, name : String, e : GlobalRegistry.Entry) : Bool do\n    e.node_id == st.me || reference_exempt(name)\n      || raw_allowed(core_own_cert(st), Map.get(st.certs, e.node_id, Map.str_cmp))\n  end\n\n  -- The certificate identity (URI) of node [id] as this node verified it:\n  -- its own for itself, a linked peer's, else \"\".\n  pfn identity_of(st : CnState, id : String) : String do\n    if id == st.me do\n      match core_own_cert(st) do\n        Some(c) -> c.node\n        None -> \"\"\n      end\n    else\n      match Map.get(st.certs, id, Map.str_cmp) do\n        Some(c) -> c.node\n        None -> \"\"\n      end\n    end\n  end\n\n  -- Record who registered each leaf a peer [from] sent: the link's verified\n  -- peer for its own bindings; for a relayed binding, what we recorded for\n  -- that same binding before, else its holder's certificate if we have it.\n  pfn stamp_leaves(st : CnState, from : String, leaves : List((String, GlobalRegistry.Entry)))\n      : List((String, GlobalRegistry.Entry)) do\n    List.map(leaves, fn kv ->\n      match kv do\n        (name, e) ->\n          let who = if e.node_id == from || e.node_id == st.me do identity_of(st, e.node_id)\n            else\n              match GlobalRegistry.entry(st.reg, name) do\n                Some(old) ->\n                  if old.node_id == e.node_id && old.pid == e.pid && old.creation == e.creation && old.registrant != \"\" do old.registrant\n                  else identity_of(st, e.node_id) end\n                None -> identity_of(st, e.node_id)\n              end\n            end\n          (name, { e with registrant: who })\n      end)\n  end\n\n  doc \"\"\"\n  The recorded registrant of binding [name] (the certificate identity of the\n  node that registered it, as this replica recorded it; \"\" when unknown), if\n  the registry holds a present binding for it. Unlike `lookup`, not hidden.\n  \"\"\"\n  fn core_registrant(st : CnState, name : String) : Option(String) do\n    match GlobalRegistry.entry(st.reg, name) do\n      Some(e) -> if e.present do Some(e.registrant) else None end\n      None -> None\n    end\n  end\n\n  pfn visible_map(st : CnState) : Map(String, GlobalPid.Pid) do\n    List.fold_left(GlobalRegistry.all_entries(st.reg), Map.empty(), fn (acc, kv) ->\n      match kv do\n        (name, e) ->\n          if visible(st, e) && reference_visible(st, name, e) do\n            Map.insert(acc, name, GlobalPid.make(e.node_id, e.pid, e.creation), Map.str_cmp)\n          else acc end\n      end)\n  end\n\n  pfn is_ours(st : CnState, name : String, p : GlobalPid.Pid) : Bool do\n    let mine = match Map.get(st.regs, name, Map.str_cmp) do\n      Some((pid, _)) -> pid == p.local_pid\n      None -> false\n    end\n    mine && p.node_id == st.me\n  end\n\n  -- The current winner of [name] in the replica, visible or not.\n  pfn winner_of(st : CnState, name : String) : Option(GlobalPid.Pid) do\n    match GlobalRegistry.entry(st.reg, name) do\n      Some(e) -> if e.present do Some(GlobalPid.make(e.node_id, e.pid, e.creation)) else None end\n      None -> None\n    end\n  end\n\n  -- Recompute visibility and report every change: to watchers (Named), and\n  -- by forgetting local registrations another holder has taken (Lost).\n  pfn refresh_names(st : CnState) : (CnState, List(CnEffect)) do\n    let new_vis = visible_map(st)\n    -- Each name once: List.dedup only drops ADJACENT duplicates, and a name\n    -- in both maps is not adjacent to itself in the appended key lists.\n    let added = List.filter(Map.keys(new_vis), fn k -> not(Map.contains_key(st.vis, k, Map.str_cmp)))\n    let names = List.append(Map.keys(st.vis), added)\n    let out = List.fold_left(names, (st, Nil), fn (acc, name) ->\n      match acc do\n        (s, effs) ->\n          let before = Map.get(s.vis, name, Map.str_cmp)\n          let after = Map.get(new_vis, name, Map.str_cmp)\n          name_change(s, effs, name, before, after)\n      end)\n    match out do\n      (st2, effs) ->\n        let done = ({ st2 with vis: new_vis }, effs)\n        done\n    end\n  end\n\n  pfn name_change(s : CnState, effs : List(CnEffect), name : String, before : Option(GlobalPid.Pid),\n                  after : Option(GlobalPid.Pid)) : (CnState, List(CnEffect)) do\n    match (before, after) do\n      (None, None) -> (s, effs)\n      (None, Some(p)) -> (s, List.append(effs, Cons(Named(name, Bound(name, p)), Nil)))\n      (Some(o), _) ->\n        let changed = match after do\n          None -> true\n          Some(p) -> not(GlobalPid.eq(o, p))\n        end\n        if not(changed) do\n          (s, effs)\n        else if is_ours(s, name, o) do\n          -- A binding made here lost to another holder's (visible or not).\n          let winner = match after do\n            Some(p) -> Some(p)\n            None -> winner_of(s, name)\n          end\n          match winner do\n            Some(w) ->\n              if GlobalPid.eq(w, o) do\n                (s, List.append(effs, Cons(Named(name, Unbound(name)), Nil)))\n              else\n                let watcher = match Map.get(s.regs, name, Map.str_cmp) do\n                  Some((_, wp)) -> Cons(Unwatch(wp), Nil)\n                  None -> Nil\n                end\n                let s2 = { s with regs: Map.remove(s.regs, name, Map.str_cmp) }\n                let out = (s2, List.append(effs, Cons(Named(name, Lost(name, w)), watcher)))\n                out\n              end\n            None -> (s, List.append(effs, Cons(Named(name, Unbound(name)), Nil)))\n          end\n        else\n          match after do\n            Some(p) -> (s, List.append(effs, Cons(Named(name, Bound(name, p)), Nil)))\n            None -> (s, List.append(effs, Cons(Named(name, Unbound(name)), Nil)))\n          end\n        end end\n    end\n  end\n\n  -- Frames carrying registry leaves to every linked peer: a REGISTRY_SYNC_RESP\n  -- whose root is `push_root()`, not this replica's root hash. A receiver\n  -- merges the leaves and does not answer. Answering a push with the whole\n  -- registry (what a root mismatch did, and still does for a node that\n  -- predates this) made every name change under session churn cost two full\n  -- dumps of the registry, tombstones included: the two nodes' roots almost\n  -- never match while names change on both, so the dumps ping-ponged, and the\n  -- registry grows by two names per session until its tombstones expire\n  -- (3 h). 400 back-to-back sessions slowed to ~1 s each, with millions of\n  -- transient objects per node. A lost push is still repaired: the link-up\n  -- sync and the periodic anti-entropy (REQ/RESP with real roots) send\n  -- everything.\n  pfn push_leaves(st : CnState, leaves : List((String, GlobalRegistry.Entry))) : List(CnEffect) do\n    match linked_ids(st) do\n      Nil -> Nil\n      ids ->\n        let bytes = NetKernel.encode_registry_sync_resp(push_root(), leaves)\n        List.map(ids, fn id -> Send(id, bytes))\n    end\n  end\n\n  -- Never a root hash (those are hex digests, or \"\" for an empty registry).\n  pfn push_root() : String do \"push\" end\n\n  pfn leaf(st : CnState, name : String) : List((String, GlobalRegistry.Entry)) do\n    match GlobalRegistry.entry(st.reg, name) do\n      Some(e) -> Cons((name, e), Nil)\n      None -> Nil\n    end\n  end\n\n  -- Tombstone our own bindings from an earlier creation (a restart reuses\n  -- local pids, so they name whatever process has that pid now). A name this\n  -- life registered again is re-registered instead, with a clock past the\n  -- merged one: our registration came from an empty replica, so its clock is\n  -- older than our previous life's binding the peers still hold, and the merge\n  -- kept that one. Tombstoning it erased the live registration on every node\n  -- (the lab's \"no access point is registered\" after a rolling restart).\n  pfn retire_stale(st : CnState) : (CnState, List(String)) do\n    let stale = List.filter(GlobalRegistry.all_entries(st.reg), fn kv ->\n      match kv do (_n, e) -> e.present && e.node_id == st.me && e.creation != st.cfg.creation end)\n    List.fold_left(stale, (st, Nil), fn (acc, kv) ->\n      match acc do\n        (s, names) ->\n          match kv do\n            (name, e) ->\n              let clock = GlobalRegistry.next_clock(s.reg, name, s.me)\n              match Map.get(s.regs, name, Map.str_cmp) do\n                Some((pid, _)) ->\n                  let r = GlobalRegistry.register_as(s.reg, name, s.me, s.cfg.creation, pid, clock,\n                                                     identity_of(s, s.me))\n                  let out = ({ s with reg: r }, Cons(name, names))\n                  out\n                None ->\n                  match GlobalRegistry.unregister_own(s.reg, name, s.me, e.creation, e.pid, clock) do\n                    Some(r) ->\n                      let out = ({ s with reg: r }, Cons(name, names))\n                      out\n                    None -> (s, names)\n                  end\n              end\n          end\n      end)\n  end\n\n  doc \"\"\"\n  Register [name] -> local pid [pid] (its Down-watcher is [watcher]). Refused\n  if another holder's binding is visible here -- the API checked the mirror\n  first, so that is a race lost: the watcher is retired and the name's\n  watchers get `Lost(name, holder)`.\n  \"\"\"\n  fn core_register(st : CnState, name : String, pid : Int, watcher : Int) : (CnState, List(CnEffect)) do\n    match core_lookup(st, name) do\n      Some(p) ->\n        if p.node_id == st.me && p.local_pid == pid do\n          core_register_ok(st, name, pid, watcher)\n        else\n          -- register() checked the mirror and returned Ok; another binding got\n          -- here first. Tell the name's watchers who holds it.\n          let out = (st, Cons(Unwatch(watcher), Cons(Named(name, Lost(name, p)), Nil)))\n          out\n        end\n      None -> core_register_ok(st, name, pid, watcher)\n    end\n  end\n\n  pfn core_register_ok(st : CnState, name : String, pid : Int, watcher : Int) : (CnState, List(CnEffect)) do\n    let clock = GlobalRegistry.next_clock(st.reg, name, st.me)\n    let old_watch = match Map.get(st.regs, name, Map.str_cmp) do\n      Some((_, w)) -> if w != watcher do Cons(Unwatch(w), Nil) else Nil end\n      None -> Nil\n    end\n    let st2 = { st with reg: GlobalRegistry.register_as(st.reg, name, st.me, st.cfg.creation, pid, clock,\n                                                        identity_of(st, st.me)),\n                        regs: Map.insert(st.regs, name, (pid, watcher), Map.str_cmp) }\n    match refresh_names(st2) do\n      (st3, effs) ->\n        let out = (st3, List.append(old_watch, List.append(push_leaves(st3, leaf(st3, name)), effs)))\n        out\n    end\n  end\n\n  doc \"Unregister [name] if this node holds it (compare-and-delete).\"\n  fn core_unregister(st : CnState, name : String) : (CnState, List(CnEffect)) do\n    match Map.get(st.regs, name, Map.str_cmp) do\n      None -> (st, Nil)\n      Some((pid, w)) ->\n        let st1 = { st with regs: Map.remove(st.regs, name, Map.str_cmp) }\n        let clock = GlobalRegistry.next_clock(st1.reg, name, st1.me)\n        match GlobalRegistry.unregister_own(st1.reg, name, st1.me, st1.cfg.creation, pid, clock) do\n          None -> (st1, Cons(Unwatch(w), Nil))\n          Some(r) ->\n            let st2 = { st1 with reg: r }\n            match refresh_names(st2) do\n              (st3, effs) ->\n                let out = (st3, Cons(Unwatch(w), List.append(push_leaves(st3, leaf(st3, name)), effs)))\n                out\n            end\n        end\n    end\n  end\n\n  doc \"A locally registered process died: unregister every name it held.\"\n  fn core_local_down(st : CnState, pid : Int) : (CnState, List(CnEffect)) do\n    let names = List.filter_map(Map.entries(st.regs), fn kv ->\n      match kv do (name, (p, _)) -> if p == pid do Some(name) else None end end)\n    List.fold_left(names, (st, Nil), fn (acc, name) ->\n      match acc do\n        (s, effs) ->\n          match core_unregister(s, name) do\n            (s2, e2) ->\n              let out = (s2, List.append(effs, e2))\n              out\n          end\n      end)\n  end\n\n  -- A REGISTRY_SYNC_REQ / RESP from [from].\n  pfn registry_frame(st : CnState, from : String, tag : Int, frame : List(Int)) : (CnState, List(CnEffect)) do\n    if tag == 5 do\n      match NetKernel.decode_registry_sync_req(frame) do\n        Err(_) -> (st, Nil)\n        Ok(rh) ->\n          if rh == GlobalRegistry.root_hash(st.reg) do (st, Nil)\n          else\n            let bytes = NetKernel.encode_registry_sync_resp(GlobalRegistry.root_hash(st.reg), GlobalRegistry.all_entries(st.reg))\n            (st, Cons(Send(from, bytes), Nil))\n          end\n      end\n    else\n      match NetKernel.decode_registry_sync_resp(frame) do\n        Err(_) -> (st, Nil)\n        Ok((rh, leaves)) ->\n          let pushed = rh == push_root()\n          let stamped = stamp_leaves(st, from, leaves)\n          let merged = if pushed do\n            List.fold_left(stamped, st.reg, fn (acc, kv) -> match kv do (name, e) -> GlobalRegistry.observe(acc, name, e) end)\n          else GlobalRegistry.diff_entries(st.reg, rh, stamped) end\n          match retire_stale({ st with reg: merged, reg_synced: true }) do\n            (st2, retired) ->\n              -- Answer a full sync with everything when the sender's state (its\n              -- root) is not what we now hold, so it can merge ours: two rounds\n              -- at most, since after merging both hold the join. A push (a\n              -- few leaves, `push_root`) is never answered: see push_leaves.\n              let reply = if pushed do Nil else\n                let mine = GlobalRegistry.root_hash(st2.reg)\n                if mine != rh do\n                  Cons(Send(from, NetKernel.encode_registry_sync_resp(mine, GlobalRegistry.all_entries(st2.reg))), Nil)\n                else Nil end\n              end\n              let retire_push = List.flat_map(retired, fn n -> push_leaves(st2, leaf(st2, n)))\n              match refresh_names(st2) do\n                (st3, effs) ->\n                  let out = (st3, List.append(reply, List.append(retire_push, effs)))\n                  out\n              end\n          end\n      end\n    end\n  end\n\n  -- \u2500\u2500 the I/O layer \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- One peer's control writer: every control frame to that peer is written\n  -- here, in mailbox order. A failed write marks it dead (the reader will\n  -- see the connection end and report it).\n  actor CtlWriter do\n    state { fd : Int, dead : Bool }\n    init  { fd: -1, dead: false }\n    on CtlUse(fd : Int) do\n      { fd: fd, dead: false }\n    end\n    on CtlWrite(bytes : List(Int)) do\n      if state.dead || state.fd < 0 do\n        state\n      else\n        match NetKernel.send_frame(state.fd, bytes) do\n          Ok(_) -> state\n          Err(_) -> { fd: state.fd, dead: true }\n        end\n      end\n    end\n    on CtlStop() do\n      { fd: state.fd, dead: true }\n    end\n    -- Close the socket here, after every write queued before it (see\n    -- release_link): a close from anywhere else could race a queued write\n    -- onto a reused fd number.\n    on CtlClose() do\n      if state.fd >= 0 do tcp_close(state.fd) else () end\n      { fd: -1, dead: true }\n    end\n  end\n\n  -- The node's backing record: what the real dictionary (`ops_of`) closes\n  -- over; `start` returns it wrapped in a `Cap(ClusterNode.Live)`, never\n  -- bare. `pid` is the Node actor's pid as an Int; the Vaults are its mirrors.\n  type CnHandle = { pid : Int, name : String, node_id : String, advertise : String,\n                  members : Vault(Member), subs : Vault(NodeEvent -> Unit), meta : Vault(Int),\n                  names : Vault(GlobalPid.Pid), claims : Vault(Int), watches : Vault(NameEvent -> Unit),\n                  links : Vault(CnLink), qs : Vault(Int), causes : Vault(String),\n                  routes : Vault(NodeSend.Delivery -> Result((), String)),\n                  closes : Vault(String -> String -> Unit),\n                  downs : Vault(DistLink.DownReason -> Unit), fired : Vault(List(Int)),\n                  failed : Vault(Int -> String -> Unit), sfailed : Vault(String -> String -> Unit),\n                  certs : Vault(NodeCert.Cert), sec : Vault(SecurityEvent -> Unit),\n                  revs : Vault(NodeCert.Revocation), op_pub : Bytes,\n                  auth : Vault(ClusterAuth.Auth), strs : Vault(String), registrants : Vault(String) }\n\n  -- Watches one registered process: its `Down` unregisters its names. `Down`\n  -- is a raw mailbox message, so the watcher reads it with `receive` (the\n  -- SessionNode.HostWatch pattern); `register` sets the monitor from outside.\n  actor RegWatch do\n    state { n : Int }\n    init  { n: 0 }\n    on WatchPid(node : Int, pid : Int) do\n      match receive() do\n        Down.Down(_, _, _) -> discard(send(pid_of_int(node), LocalDown(pid)))\n      end\n      { n: state.n + 1 }\n    end\n  end\n\n  actor ClusterNodeActor do\n    state { st : CnState, h : CnHandle, started : Bool }\n    init  { st: core_new(config(\"\", 0, \"\", Nil, \"\", 0), 0),\n            h: { pid: 0, name: \"\", node_id: \"\", advertise: \"\",\n                 members: Vault.new(\"cluster_node_unset_members\"),\n                 subs: Vault.new(\"cluster_node_unset_subs\"),\n                 meta: Vault.new(\"cluster_node_unset_meta\"),\n                 names: Vault.new(\"cluster_node_unset_names\"),\n                 claims: Vault.new(\"cluster_node_unset_claims\"),\n                 watches: Vault.new(\"cluster_node_unset_watches\"),\n                 links: Vault.new(\"cluster_node_unset_links\"),\n                 qs: Vault.new(\"cluster_node_unset_qs\"),\n                 causes: Vault.new(\"cluster_node_unset_causes\"),\n                 routes: Vault.new(\"cluster_node_unset_routes\"),\n                 closes: Vault.new(\"cluster_node_unset_closes\"),\n                 downs: Vault.new(\"cluster_node_unset_downs\"),\n                 fired: Vault.new(\"cluster_node_unset_fired\"),\n                 failed: Vault.new(\"cluster_node_unset_failed\"),\n                 sfailed: Vault.new(\"cluster_node_unset_sfailed\"),\n                 certs: Vault.new(\"cluster_node_unset_certs\"),\n                 sec: Vault.new(\"cluster_node_unset_sec\"),\n                 revs: Vault.new(\"cluster_node_unset_revs\"), op_pub: Bytes.empty(),\n                 auth: Vault.new(\"cluster_node_unset_auth\"), strs: Vault.new(\"cluster_node_unset_strs\"),\n                 registrants: Vault.new(\"cluster_node_unset_registrants\") },\n            started: false }\n    on Boot(st0 : CnState, h0 : CnHandle) do\n      { st: st0, h: h0, started: true }\n    end\n    on Tick(now : Int) do\n      if state.started do\n        resend_fires(state.st, state.h, now)\n        step_io(state.st, state.h, core_tick(state.st, now), state.started)\n      else state end\n    end\n    on Accepted(fd : Int, id : String, name : String, role : String, addr : String, creation : Int,\n                cert : Option(NodeCert.Cert)) do\n      if state.started do\n        on_accepted(core_peer_cert(state.st, id, cert), state.h, fd, id, name, role, addr, creation)\n      else\n        -- A handshake that finished after stop(): nothing may be installed.\n        tcp_close(fd)\n        state\n      end\n    end\n    on Dialed(addr : String, id : String, name : String, peer_addr : String, creation : Int, cfd : Int, dfd : Int,\n              cert : Option(NodeCert.Cert)) do\n      if state.started do\n        let cw = start_writers(state.h, cfd, dfd)\n        let st1 = core_peer_cert(state.st, id, cert)\n        step_io(st1, state.h, core_dialed_bound(st1, addr, id, name, peer_addr, creation, cfd, dfd, cw, NetKernel.link_binding(cfd)), state.started)\n      else\n        tcp_close(cfd)\n        tcp_close(dfd)\n        state\n      end\n    end\n    on SeedIsSelf(addr : String) do\n      { st: core_seed_self(state.st, addr), h: state.h, started: state.started }\n    end\n    on DialFailed(addr : String, now : Int, refused : Bool) do\n      { st: core_dial_failed(state.st, now, addr, refused), h: state.h, started: state.started }\n    end\n    on CtlFrame(from : String, gen : Int, tag : Int, frame : List(Int)) do\n      if current_gen(state.st, from, gen) do\n        if tag == tag_cert_update() do\n          match core_peer_cert_update(state.st, from, frame, unix_time_ms() / 1000) do\n            Ok((st1, c)) ->\n              security(state.h, CertReplaced(from, c.serial))\n              step_io(st1, state.h, (st1, Nil), state.started)\n            Err(why) ->\n              security(state.h, CertRefused(from, why))\n              state\n          end\n        else\n          step_io(state.st, state.h, core_frame(state.st, from, tag, frame), state.started)\n        end\n      else\n        state\n      end\n    end\n    -- This node's certificate, replaced (`h_replace_cert` has checked it and\n    -- set it for handshakes): dials use it now, and every peer is told.\n    on ReplaceCert(signed : NodeCert.Signed, sk : Bytes) do\n      let out = core_replace_cert(state.st, signed, sk)\n      match out do\n        (st1, _) -> Vault.set(state.h.auth, \"a\", st1.cfg.auth)\n      end\n      step_io(state.st, state.h, out, state.started)\n    end\n    on LinkClosed(id : String, gen : Int) do\n      step_io(state.st, state.h, core_link_closed(state.st, id, gen), state.started)\n    end\n    on Register(name : String, pid : Int, watcher : Int) do\n      -- Checked HERE, in the actor's turn: a pid that died before this turn\n      -- has had its Down (and the watcher's LocalDown) race this message, so\n      -- registering it would leave a binding to a dead process forever. One\n      -- that dies after this check is unregistered by the LocalDown that is\n      -- then queued behind this turn.\n      let next = if is_alive(pid_of_int(pid)) do\n        step_io(state.st, state.h, core_register(state.st, name, pid, watcher), state.started)\n      else\n        step_io(state.st, state.h, (state.st, Cons(Unwatch(watcher), Nil)), state.started)\n      end\n      -- step_io has mirrored the outcome into h.names; only now drop the\n      -- claim h_register took, so a racing register always sees one of them.\n      release_claim(state.h.claims, name, pid)\n      next\n    end\n    on Revoke(r : NodeCert.SignedRevocation) do\n      step_io(state.st, state.h, core_revoke(state.st, r), state.started)\n    end\n    on Unregister(name : String) do\n      step_io(state.st, state.h, core_unregister(state.st, name), state.started)\n    end\n    on LocalDown(pid : Int) do\n      step_io(state.st, state.h, core_local_down(state.st, pid), state.started)\n    end\n    -- A link reader, the ticker or the acceptor found its code epoch draining\n    -- and stopped (see \"moving to a new code epoch\"): it carries on in a task\n    -- spawned HERE, on this actor's epoch, which its marker has already\n    -- advanced. A reader is respawned even after stop: it must still see its\n    -- connection end and release it.\n    on MoveReader(kind : Int, l : CnLink, frame : List(Int), rest : List(Int)) do\n      let node = pid_of_int(state.h.pid)\n      let h = state.h\n      let creation = state.st.cfg.creation\n      let not_before = unix_time_ms() + move_interval_ms()\n      let _t = if kind == 0 do task_spawn(fn _ -> read_control(node, h, l, Some(frame), rest, not_before))\n               else task_spawn(fn _ -> read_data(node, h, creation, l, Some(frame), rest, not_before)) end\n      state\n    end\n    on MoveTicker() do\n      let node = pid_of_int(state.h.pid)\n      let h = state.h\n      let files = state.st.cfg.cert_files\n      let tick_ms = state.st.cfg.tick_ms\n      let not_before = unix_time_ms() + move_interval_ms()\n      let _t = task_spawn(fn _ -> tick_loop(node, h, files, tick_ms, not_before))\n      state\n    end\n    on MoveAcceptor() do\n      let h = state.h\n      let listen_fd = Vault.get_or(h.meta, \"listen_fd\", -1)\n      if Vault.get(h.meta, \"stopped\") != None do\n        -- Nobody is parked on the listen socket now: closing it is safe.\n        tcp_close(listen_fd)\n      else\n        let node = pid_of_int(h.pid)\n        let cfg = state.st.cfg\n        let me = NodeIdentity.make(cfg.name, \"pk-\" ++ cfg.name, cfg.creation)\n        let meta = h.meta\n        let not_before = unix_time_ms() + move_interval_ms()\n        let _t = task_spawn(fn _ -> accept_loop(node, h, cfg, me, listen_fd, meta, not_before))\n        ()\n      end\n      state\n    end\n    on Shutdown() do\n      let h = state.h\n      let _ = List.map(Map.values(state.st.links), fn l -> do\n        drop_link(l)\n        release_link(h, l, 3)\n      end)\n      -- Half-assembled inbound pairs own their fds outright.\n      let _ = List.map(Map.values(state.st.halves), fn hf -> close_half(hf))\n      { st: { state.st with stopped: true, links: Map.empty(), halves: Map.empty() }, h: state.h, started: false }\n    end\n  end\n\n  type NodeActorState = { st : CnState, h : CnHandle, started : Bool }\n\n  pfn node_pid(h : CnHandle) do pid_of_int(h.pid) end\n\n  -- Evaluate for effect. (`let _ = x` followed by a `()` line parses as the\n  -- application `x()`: the let-then-paren trap.)\n  pfn discard(_x) : () do () end\n\n  pfn current_gen(st : CnState, id : String, gen : Int) : Bool do\n    match Map.get(st.links, id, Map.str_cmp) do\n      Some(l) -> l.gen == gen\n      None -> false\n    end\n  end\n\n  pfn start_writer(fd : Int) : Int do\n    let w = spawn(CtlWriter)\n    send(w, CtlUse(fd))\n    pid_to_int(w)\n  end\n\n  pfn data_budget() : Int do 262144 end\n\n  -- A link's two writers: the control writer (its pid is the link's `cw`)\n  -- and the data connection's NodeQueue writer (credit flow control), kept\n  -- in the handle's `qs` by the control fd.\n  pfn start_writers(h : CnHandle, cfd : Int, dfd : Int) : Int do\n    let cw = start_writer(cfd)\n    match NodeQueue.start(dfd, data_budget()) do\n      (w, _) -> Vault.set(h.qs, \"q\" ++ int_to_string(cfd), pid_to_int(w))\n    end\n    cw\n  end\n\n  pfn drop_link(l : CnLink) : () do\n    send(pid_of_int(l.cw), CtlStop())\n    tcp_shutdown(l.cfd)\n    if l.dfd >= 0 do tcp_shutdown(l.dfd) else () end\n  end\n\n  -- A link's fds are closed once EVERY party that may touch them is done:\n  -- the node's drop (after which nothing new is queued to its writers) and\n  -- both readers (a close under a parked reader drops its kqueue/epoll\n  -- registration and it never wakes). Closing earlier would also let a\n  -- later shutdown -- or a queued write -- land on the fd number after the OS\n  -- reused it for another connection. The close itself goes through each\n  -- writer's mailbox, behind any write already queued. [need] is 3 for an\n  -- installed link (drop + two readers), 1 for one never installed.\n  pfn release_link(h : CnHandle, l : CnLink, need : Int) : () do\n    let key = \"rel\" ++ int_to_string(l.gen)\n    let n = Vault.incr(h.meta, key, 1)\n    if n == need do\n      Vault.drop(h.meta, key)\n      -- Every reader is done: the connection's MAC state goes with it (the\n      -- fd numbers are about to be reused).\n      NetKernel.forget(l.cfd)\n      if l.dfd >= 0 do NetKernel.forget(l.dfd) else () end\n      discard(send(pid_of_int(l.cw), CtlClose()))\n      let qk = \"q\" ++ int_to_string(l.cfd)\n      -- Before the fds close: a new connection may reuse the number.\n      Vault.drop(h.meta, data_closed_key(l))\n      match Vault.get(h.qs, qk) do\n        Some(w) ->\n          Vault.drop(h.qs, qk)\n          NodeQueue.close_fd((pid_of_int(w), l.dfd))\n        None -> tcp_close(l.dfd)\n      end\n    else () end\n  end\n\n  pfn close_half(hf : CnHalf) : () do\n    if hf.cfd >= 0 do\n      NetKernel.forget(hf.cfd)\n      tcp_close(hf.cfd)\n    else () end\n    if hf.dfd >= 0 do\n      NetKernel.forget(hf.dfd)\n      tcp_close(hf.dfd)\n    else () end\n  end\n\n  -- Pair up an accepted connection with its other half; a complete pair is\n  -- a link (dialled by the peer).\n  pfn on_accepted(st : CnState, h : CnHandle, fd : Int, id : String, name : String, role : String,\n                  addr : String, creation : Int) : NodeActorState do\n    let old = match Map.get(st.halves, id, Map.str_cmp) do\n      Some(hf) -> if hf.creation == creation do hf else { cfd: -1, dfd: -1, name: name, addr: addr, creation: creation } end\n      None -> { cfd: -1, dfd: -1, name: name, addr: addr, creation: creation }\n    end\n    let hf = if role == Handshake.role_data() do { old with dfd: fd } else { old with cfd: fd } end\n    if hf.cfd >= 0 && hf.dfd >= 0 do\n      let st1 = { st with halves: Map.remove(st.halves, id, Map.str_cmp) }\n      let cw = start_writers(h, hf.cfd, hf.dfd)\n      step_io(st1, h, core_linked_bound(st1, id, hf.name, hf.addr, hf.creation, hf.cfd, hf.dfd, id, cw, NetKernel.link_binding(hf.cfd)), true)\n    else\n      { st: { st with halves: Map.insert(st.halves, id, hf, Map.str_cmp) }, h: h, started: true }\n    end\n  end\n\n  -- Perform a core transition's effects and mirror the member view.\n  pfn step_io(_st0 : CnState, h : CnHandle, out : (CnState, List(CnEffect)), started : Bool) : NodeActorState do\n    match out do\n      (st, effs) ->\n        let _ = List.map(effs, fn e -> perform(st, h, e))\n        mirror(st, h)\n        { st: st, h: h, started: started }\n    end\n  end\n\n  pfn perform(st : CnState, h : CnHandle, e : CnEffect) : () do\n    match e do\n      Send(id, bytes) ->\n        match Map.get(st.links, id, Map.str_cmp) do\n          Some(l) -> discard(send(pid_of_int(l.cw), CtlWrite(bytes)))\n          None -> ()\n        end\n      Dial(addr) ->\n        let me = NodeIdentity.make(st.cfg.name, \"pk-\" ++ st.cfg.name, st.cfg.creation)\n        let node = pid_of_int(h.pid)\n        let cfg = st.cfg\n        discard(task_spawn(fn _ -> dial(node, h, cfg, me, addr)))\n      Install(l) ->\n        -- The peer's certificate, before its readers start: the data reader\n        -- checks raw sends against it, and `mirror` runs only after the\n        -- effects.\n        let _ = match Map.get(st.certs, l.node_id, Map.str_cmp) do\n          Some(pc) -> Vault.set(h.certs, l.node_id, pc)\n          None -> ()\n        end\n        let node = pid_of_int(h.pid)\n        let _ = task_spawn(fn _ -> read_control(node, h, l, None, Nil, 0))\n        discard(task_spawn(fn _ -> read_data(node, h, st.cfg.creation, l, None, Nil, 0)))\n      Drop(l, why) ->\n        -- The data reader reads the cause when its connection ends, and\n        -- tells the routes; set before the sockets are shut.\n        Vault.set(h.causes, \"c\" ++ int_to_string(l.cfd), why)\n        -- Off the mirror NOW, not at the `mirror` after this step's\n        -- effects: a session forming meanwhile on another scheduler took\n        -- the dropped pair's queue from `session_queue_for`, and its reader\n        -- could tell the close handlers before that session installed its\n        -- own, and its `recheck_links` still saw the pair as current.\n        match Vault.get(h.links, l.node_id) do\n          Some(cur) -> if cur.gen == l.gen do Vault.drop(h.links, l.node_id) else () end\n          None -> ()\n        end\n        drop_link(l)\n        release_link(h, l, 3)\n      Discard(l) ->\n        -- Never installed: no reader will ever release it.\n        drop_link(l)\n        release_link(h, l, 1)\n      Named(name, ev) -> tell_watchers(h, name ++ watch_sep(), ev)\n      Unwatch(w) -> if w > 0 do kill(pid_of_int(w)) else () end\n      Emit(NodeDead(i, why)) ->\n        monitors_node_down(h, i.node_id)\n        let _ = dist_monitor_forget_node(i.node_id)\n        emit_all(h, NodeDead(i, why))\n      Emit(ev) -> emit_all(h, ev)\n    end\n  end\n\n  pfn emit_all(h : CnHandle, ev : NodeEvent) : () do\n    discard(List.map(Vault.all(h.subs), fn kv -> emit_one(kv, ev)))\n  end\n\n  pfn emit_one(kv : (String, NodeEvent -> Unit), ev : NodeEvent) : () do\n    match kv do\n      (_k, f) -> f(ev)\n    end\n  end\n\n  pfn tell_watchers(h : CnHandle, prefix : String, ev : NameEvent) : () do\n    discard(List.map(Vault.all(h.watches), fn kv -> tell_watcher(kv, prefix, ev)))\n  end\n\n  pfn tell_watcher(kv : (String, NameEvent -> Unit), prefix : String, ev : NameEvent) : () do\n    match kv do\n      (k, f) -> if String.starts_with(k, prefix) do f(ev) else () end\n    end\n  end\n\n  pfn mirror(st : CnState, h : CnHandle) : () do\n    let _ = List.map(core_members(st), fn m -> Vault.set(h.members, m.node_id, m))\n    let _ = Vault.set(h.meta, \"links\", Map.size(st.links))\n    let _ = List.map(Map.entries(st.certs), fn kv -> match kv do (k, c) -> Vault.set(h.certs, k, c) end)\n    let _ = List.map(Vault.keys(h.certs), fn k ->\n      if Map.contains_key(st.certs, k, Map.str_cmp) do () else Vault.drop(h.certs, k) end)\n    let _ = List.map(st.revs, fn r -> Vault.set(h.revs, Bytes.to_hex(r.signature), r.rev))\n    let _ = List.map(Vault.keys(h.links), fn k ->\n      if Map.contains_key(st.links, k, Map.str_cmp) do () else Vault.drop(h.links, k) end)\n    let _ = List.map(Map.entries(st.links), fn kv -> match kv do (k, l) -> Vault.set(h.links, k, l) end)\n    -- Our own present bindings from an earlier creation: retire_stale keeps\n    -- this at 0 once the registry has synced (observable for tests).\n    let stale = List.length(List.filter(GlobalRegistry.all_entries(st.reg), fn kv ->\n      match kv do (_n, e) -> e.present && e.node_id == st.me && e.creation != st.cfg.creation end))\n    let _ = Vault.set(h.meta, \"stale_bindings\", stale)\n    let _ = Vault.set(h.meta, \"reg_synced\", if st.reg_synced do 1 else 0 end)\n    -- When a peer last showed this node as rejoining: stamped here, on the\n    -- step that counted it (the core has no clock).\n    let _ = if st.remembered > Vault.get_or(h.meta, \"remembered\", 0) do\n      Vault.set(h.meta, \"remembered\", st.remembered)\n      Vault.set(h.meta, \"rejoined_at\", unix_time_ms())\n    else () end\n    let _ = List.map(Vault.keys(h.names), fn k ->\n      if Map.contains_key(st.vis, k, Map.str_cmp) do () else Vault.drop(h.names, k) end)\n    discard(List.map(Map.entries(st.vis), fn kv -> match kv do (k, p) -> Vault.set(h.names, k, p) end))\n    let _ = List.map(Vault.keys(h.registrants), fn k ->\n      if core_registrant(st, k) == None do Vault.drop(h.registrants, k) else () end)\n    discard(List.map(GlobalRegistry.all_entries(st.reg), fn kv ->\n      match kv do (k, e) -> if e.present do Vault.set(h.registrants, k, e.registrant) else () end end))\n  end\n\n  -- \u2500\u2500 tasks \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn split_addr(addr : String) : Option((String, Int)) do\n    match String.split_first(addr, \":\") do\n      None -> None\n      Some((host, p)) ->\n        match String.to_int(p) do\n          Ok(port) -> Some((host, port))\n          Err(_) -> None\n        end\n    end\n  end\n\n  pfn refused_msg(e : String) : Bool do\n    String.contains(e, \"refused\")\n  end\n\n  pfn dial_one(h : CnHandle, cfg : CnConfig, me : NodeIdentity.Identity, host : String, port : Int, role : String)\n      : Result((Int, NetKernel.Authed), (String, Bool)) do\n    match Socket.connect_timeout(host, port, cfg.dial_timeout_ms) do\n      Err(e) ->\n        let msg = Socket.error_message(e)\n        Err((msg, refused_msg(msg)))\n      Ok(fd) ->\n        match NetKernel.handshake_auth(fd, me, h_auth(h, cfg.auth), NetKernel.fresh_nonce(), role,\n                                       cfg.advertise, cfg.handshake_timeout_ms) do\n          Err(e) ->\n            tcp_close(fd)\n            security(h, HandshakeRejected(host ++ \":\" ++ int_to_string(port), e))\n            Err((e, false))\n          Ok(a) -> Ok((fd, a))\n        end\n    end\n  end\n\n  pfn security(h : CnHandle, ev : SecurityEvent) : () do\n    discard(List.map(Vault.all(h.sec), fn kv -> match kv do (_k, f) -> f(ev) end))\n  end\n\n  -- A raw frame between this node and [peer_id]: allowed? (Its own node,\n  -- the loopback, always.)\n  pfn h_raw_ok(h : CnHandle, peer_id : String) : Bool do\n    peer_id == h.node_id || raw_allowed(h_own(h), Vault.get(h.certs, peer_id))\n  end\n\n  -- This node's credentials as of now ([dflt] before `start` has set them).\n  pfn h_auth(h : CnHandle, dflt : ClusterAuth.Auth) : ClusterAuth.Auth do\n    match Vault.get(h.auth, \"a\") do\n      Some(a) -> a\n      None -> dflt\n    end\n  end\n\n  -- This node's certificate as of now, or None in shared-secret mode.\n  pfn h_own(h : CnHandle) : Option(NodeCert.Cert) do\n    match Vault.get(h.auth, \"a\") do\n      Some(a) ->\n        match a do\n          ClusterAuth.Certified(cr) -> Some(cr.signed.cert)\n          ClusterAuth.Secret(_) -> None\n        end\n      None -> None\n    end\n  end\n\n  -- Count and report a refused raw send.\n  pfn note_raw_refused(h : CnHandle, peer_id : String, what : String) : () do\n    let _ = Vault.incr(h.meta, \"raw_refused\", 1)\n    security(h, RawSendRefused(peer_id, what))\n  end\n\n  -- Open a pair to [addr]: control, then data (the order the acceptor's\n  -- pairing does not depend on, but a pre-split peer would).\n  pfn dial(node, h : CnHandle, cfg : CnConfig, me : NodeIdentity.Identity, addr : String) : Int do\n    match split_addr(addr) do\n      None ->\n        send(node, DialFailed(addr, unix_time_ms(), false))\n        0\n      Some((host, port)) ->\n        match dial_one(h, cfg, me, host, port, Handshake.role_control()) do\n          Err((_, refused)) ->\n            send(node, DialFailed(addr, unix_time_ms(), refused))\n            0\n          Ok((cfd, a)) ->\n            let peer = a.identity\n            let peer_addr = a.addr\n            match dial_one(h, cfg, me, host, port, Handshake.role_data()) do\n              Err((_, refused)) ->\n                tcp_close(cfd)\n                send(node, DialFailed(addr, unix_time_ms(), refused))\n                0\n              Ok((dfd, a2)) ->\n                if a2.identity.node_id != peer.node_id do\n                  -- Two dials of one address reached two nodes: trust neither.\n                  tcp_close(cfd)\n                  tcp_close(dfd)\n                  send(node, DialFailed(addr, unix_time_ms(), false))\n                  0\n                else if peer.node_id == node_id_of(cfg.name) do\n                  -- We dialled ourselves (a seed list naming this node).\n                  tcp_close(cfd)\n                  tcp_close(dfd)\n                  send(node, SeedIsSelf(addr))\n                  0\n                else\n                  send(node, Dialed(addr, peer.node_id, peer.name, peer_addr, peer.incarnation, cfd, dfd, a.cert))\n                  1\n                end end\n            end\n        end\n    end\n  end\n\n  -- The control reader. SWIM, member and registry frames go to the node\n  -- actor (the core's); the data plane's control frames are handled here,\n  -- in the reader's own turn, since they touch no core state:\n  --   7 MONITOR_REQ   register the remote watcher with the C registry. With\n  --                   fd -1: the fire's own write then fails at once and it\n  --                   waits in the registry's pending list, which the node\n  --                   resends through this link's control writer -- every\n  --                   byte on a control socket has ONE writer\n  --   8 MONITOR_FIRE  a monitored process died: call the local watchers,\n  --                   ack (every copy: the resend is at-least-once)\n  --   10 DELIVERY_FAILED  to the failure handler\n  --   11 CREDIT       to this link's data queue\n  --   12 MONITOR_ACK  forget the pending fire\n  pfn read_control(node, h : CnHandle, l : CnLink, first : Option(List(Int)), buf : List(Int),\n                   not_before : Int) : Int do\n    let on_frame = fn (tag, frame) -> control_frame(node, h, l, tag, frame)\n    match first do\n      Some(f) -> on_frame(PeerReader.tag_of(f), f)\n      None -> ()\n    end\n    match read_link(l.cfd, buf, not_before, on_frame) do\n      Some((frame, rest)) ->\n        send(node, MoveReader(0, l, frame, rest))\n        0\n      None ->\n        send(node, LinkClosed(l.node_id, l.gen))\n        release_link(h, l, 3)\n        0\n    end\n  end\n\n  -- A DELIVERY_FAILED from [from_node] for our frame [seq]: a session\n  -- frame's (a negative seq, `session_seq`) goes to the session that sent it\n  -- (`on_session_failed`), anything else to the node's handler\n  -- (`on_delivery_failed`).\n  pfn delivery_failed(h : CnHandle, from_node : String, seq : Int, reason : String) : () do\n    if seq < 0 do\n      match Vault.get(h.sfailed, int_to_string(session_seq_key(seq))) do\n        Some(f) -> f(from_node, reason)\n        None -> ()\n      end\n    else\n      match Vault.get(h.failed, \"f\") do\n        Some(f) -> f(seq, reason)\n        None -> ()\n      end\n    end\n  end\n\n  pfn control_frame(node, h : CnHandle, l : CnLink, tag : Int, frame : List(Int)) : () do\n    if tag == 7 do\n      match DistLink.decode_req(frame) do\n        Ok((_claimed, watcher_ref, target_pid)) -> dist_monitor_register(target_pid, l.node_id, watcher_ref, -1)\n        Err(_) -> ()\n      end\n    else if tag == 8 do\n      on_fire(h, l, frame)\n    else if tag == 10 do\n      match NodeSend.decode_failed(frame) do\n        Ok((seq, reason)) ->\n          delivery_failed(h, l.node_id, seq, reason)\n        Err(_) -> ()\n      end\n    else if tag == 11 do\n      match NodeQueue.decode_credit(frame) do\n        Ok(total) ->\n          match Vault.get(h.qs, \"q\" ++ int_to_string(l.cfd)) do\n            Some(w) -> NodeQueue.credit((pid_of_int(w), l.dfd), total)\n            None -> ()\n          end\n        Err(_) -> ()\n      end\n    else if tag == 12 do\n      match DistLink.decode_ack(frame) do\n        Ok((target_pid, watcher_ref)) -> dist_monitor_ack(target_pid, watcher_ref)\n        Err(_) -> ()\n      end\n    else\n      discard(send(node, CtlFrame(l.node_id, l.gen, tag, frame)))\n    end end end end end\n  end\n\n  -- The data reader: every ACTOR_MSG goes to its route -- by destination\n  -- pid, else by message type -- in this reader's turn (the node actor is\n  -- never on the data path). A stale creation, no route, or a route's Err is\n  -- answered with DELIVERY_FAILED on the control connection. Consumption is\n  -- announced with CREDIT (the receiver half of NodeQueue's flow control).\n  -- When the connection ends, every close handler hears (peer, why): why is\n  -- the cause the node recorded before shutting it (\"node X dead: ...\", or\n  -- \"replaced\"), else \"connection lost\". Told from THIS task, behind every\n  -- delivery it made, so a route that forwards both to one mailbox sees the\n  -- close after the last delivery (the ordering SessionNode's drain rule\n  -- depends on).\n  pfn read_data(node, h : CnHandle, creation : Int, l : CnLink, first : Option(List(Int)), buf : List(Int),\n                not_before : Int) : Int do\n    let on_frame = fn (tag, frame) -> data_frame(h, creation, l, tag, frame)\n    match first do\n      Some(f) -> on_frame(PeerReader.tag_of(f), f)\n      None -> ()\n    end\n    match read_link(l.dfd, buf, not_before, on_frame) do\n      Some((frame, rest)) ->\n        send(node, MoveReader(1, l, frame, rest))\n        0\n      None ->\n        -- No session may link to this connection from here on: mark it\n        -- BEFORE the close handlers run (`h_queue_for`). Its queue stays in\n        -- `h.qs` until every reader has released it (`release_link`), so a\n        -- session forming in between got the dead queue and missed the\n        -- close it was told before it subscribed.\n        Vault.set(h.meta, data_closed_key(l), 1)\n        data_closed(h, l)\n        send(node, LinkClosed(l.node_id, l.gen))\n        release_link(h, l, 3)\n        0\n    end\n  end\n\n  pfn data_closed_key(l : CnLink) : String do \"dc\" ++ int_to_string(l.cfd) end\n\n  pfn data_closed(h : CnHandle, l : CnLink) : () do\n    let why = Vault.get_or(h.causes, \"c\" ++ int_to_string(l.cfd), \"connection lost\")\n    Vault.drop(h.causes, \"c\" ++ int_to_string(l.cfd))\n    discard(List.map(Vault.all(h.closes), fn kv -> match kv do (_k, f) -> f(l.node_id, why) end))\n  end\n\n  pfn data_frame(h : CnHandle, creation : Int, l : CnLink, tag : Int, frame : List(Int)) : () do\n    if tag == NodeSend.tag_actor_msg() do\n      match NodeSend.decode_msg(frame) do\n        Err(_) -> ()\n        Ok(d0) ->\n          -- The sender is the link's verified peer, never a claim in the frame.\n          let d = { d0 with from_node: l.node_id }\n          announce_consumed(h, l, List.length(frame) + 4)\n          -- The delivery's origin rides the mailbox node of whatever the\n          -- route sends (DD step-6 follow-up 1): an actor that later drops\n          -- the message (a hot deploy changed its message type) answers\n          -- DELIVERY_FAILED through `delivery_failed_watch`'s hook, on\n          -- this link's control writer. Set around the route only: the\n          -- route runs to completion in this task's turn.\n          delivery_origin_set(l.cw, d.seq)\n          let outcome = if d.to_creation != creation do\n            Err(\"stale creation \" ++ int_to_string(d.to_creation) ++ \", node is at \" ++ int_to_string(creation))\n          else deliver_local(h, d) end\n          delivery_origin_clear()\n          match outcome do\n            Ok(_) -> ()\n            Err(reason) -> discard(send(pid_of_int(l.cw), CtlWrite(NodeSend.encode_failed(d.seq, reason))))\n          end\n      end\n    else ()\n    end\n  end\n\n  -- \u2500\u2500 moving to a new code epoch \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- A task runs the code of the epoch it was spawned in and never advances\n  -- (plan II.4.3). The node's long-lived tasks -- each link's two readers,\n  -- the ticker, the acceptor -- would keep the epoch of the link's forming\n  -- (or of the node's start) for good: a reader would route every later\n  -- delivery through that epoch's code, and its `send`s stamp the message\n  -- with that epoch, so after a deploy that changes an actor's message type\n  -- a delivery from a sender already on the new format went through\n  -- migrate_msg or was dropped; and the old epoch stayed pinned. So each of\n  -- them, once it finds its epoch draining (`epoch_draining()`: true after a\n  -- deploy until nothing pins the old epoch), hands its work to a task the\n  -- node actor spawns (MoveReader/MoveTicker/MoveAcceptor): that actor has\n  -- passed its marker, so the task runs the new code. Topology's placement\n  -- loop moves the same way.\n  --\n  -- A reader checks after it reads a frame and BEFORE routing it, and hands\n  -- over that frame and the bytes it read past it: the new reader routes\n  -- the frame first, so order is kept and nothing is read twice (the MAC\n  -- state is the fd's, not the task's). A reader of a quiet connection moves\n  -- at its next frame (a control connection carries SWIM every period), the\n  -- acceptor at its next connection, the ticker within a tick.\n  --\n  -- A drain can also cover the CURRENT epoch (`SessionNode.drain_epochs`,\n  -- Topology's SIGTERM drain): a moved task is then still draining. It does\n  -- not move again before [not_before] (move_interval_ms() after it was\n  -- spawned), which bounds that to one move per task per interval, and still\n  -- lets a task moved just before a second deploy follow it.\n\n  pfn move_interval_ms() : Int do 1000 end\n\n  -- Read [fd]'s frames, handing each to [on_frame], until the connection\n  -- ends (None) or this task's epoch is draining at or after [not_before]:\n  -- then Some((frame, rest)), the frame just read (not yet handled) and the\n  -- bytes read past it.\n  @[diverges] pfn read_link(fd : Int, buf : List(Int), not_before : Int, on_frame : Int -> List(Int) -> ())\n      : Option((List(Int), List(Int))) do\n    match NetKernel.recv_frame(fd, buf) do\n      Err(_) -> None\n      Ok((frame, rest)) ->\n        if epoch_draining() && unix_time_ms() >= not_before do Some((frame, rest))\n        else\n          on_frame(PeerReader.tag_of(frame), frame)\n          read_link(fd, rest, not_before, on_frame)\n        end\n    end\n  end\n\n  -- The actor loop dropped a remote delivery it had already accepted (a hot\n  -- deploy changed the actor's message type and nothing converted the old\n  -- format): answer DELIVERY_FAILED as the reader would for a route's Err.\n  -- [conn] is the link's control-writer pid the reader stamped\n  -- (`delivery_origin_set`), or negative for the loopback. Runs in the\n  -- dropping actor's turn; it only sends. One hook per process, installed\n  -- by the first `start` (a later node's handle replaces it: the loopback\n  -- handler is per node, the writer pids are not).\n  pfn delivery_failed_hook(h : CnHandle, conn : Int, seq : Int, reason : String) : () do\n    if conn < 0 do delivery_failed(h, h.node_id, seq, reason)\n    else\n      discard(send(pid_of_int(conn), CtlWrite(NodeSend.encode_failed(seq, reason))))\n    end\n  end\n\n  -- A delivery from [d.from_node] (the link's peer, or this node for the\n  -- loopback). A session route (\"s<pid>\") takes session traffic from any\n  -- certified peer; everything else is a raw send, refused (counted,\n  -- reported, and answered DELIVERY_FAILED by the caller) unless both\n  -- certificates carry raw_send (step 11b; see \"raw sends\" above).\n  pfn deliver_local(h : CnHandle, d : NodeSend.Delivery) : Result((), String) do\n    let raw_ok = h_raw_ok(h, d.from_node)\n    match Vault.get(h.routes, \"s\" ++ int_to_string(d.to_local_pid)) do\n      Some(f) -> if raw_ok || is_session_tag(d.type_tag) do f(d) else refuse_inbound(h, d) end\n      None -> if raw_ok do deliver_raw(h, d) else refuse_inbound(h, d) end\n    end\n  end\n\n  pfn deliver_raw(h : CnHandle, d : NodeSend.Delivery) : Result((), String) do\n    match Vault.get(h.routes, \"p\" ++ int_to_string(d.to_local_pid)) do\n      Some(f) -> f(d)\n      None ->\n        match Vault.get(h.routes, \"t\" ++ d.type_tag) do\n          Some(f) -> f(d)\n          None -> Err(\"no route to pid \" ++ int_to_string(d.to_local_pid) ++ \" for \" ++ d.type_tag)\n        end\n    end\n  end\n\n  pfn refuse_inbound(h : CnHandle, d : NodeSend.Delivery) : Result((), String) do\n    note_raw_refused(h, d.from_node, \"inbound \" ++ d.type_tag)\n    Err(\"not authorized: raw send of \" ++ d.type_tag ++ \" refused (certificate mode: both nodes' certificates need raw_send)\")\n  end\n\n  -- CREDIT every quarter budget consumed (NodeQueue.consumed's rule), sent\n  -- through the control writer rather than written to the socket directly.\n  pfn announce_consumed(h : CnHandle, l : CnLink, len : Int) : () do\n    let key = \"credit\" ++ int_to_string(l.cfd)\n    let total = Vault.incr(h.meta, key, len)\n    let last = Vault.get_or(h.meta, key ++ \"_sent\", 0)\n    if total - last >= data_budget() / 4 do\n      Vault.set(h.meta, key ++ \"_sent\", total)\n      discard(send(pid_of_int(l.cw), CtlWrite(NodeQueue.encode_credit(total))))\n    else () end\n  end\n\n  -- \u2500\u2500 remote monitors \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- A local watcher of a remote process is a closure under\n  -- \"m<node>|<target_pid>|<ref>\"; the ref is what goes on the wire as the\n  -- watcher pid (MONITOR_REQ's third field), so a fire for a target reaches\n  -- every watcher of it here and each is acked by its ref.\n\n  pfn mkey(node_id : String, target_pid : Int) : String do\n    \"m\" ++ node_id ++ \"|\" ++ int_to_string(target_pid) ++ \"|\"\n  end\n\n  pfn ref_of_key(k : String) : Int do\n    match List.reverse(String.split(k, \"|\")) do\n      Cons(r, _) ->\n        match String.to_int(r) do\n          Ok(n) -> n\n          Err(_) -> 0\n        end\n      Nil -> 0\n    end\n  end\n\n  pfn on_fire(h : CnHandle, l : CnLink, frame : List(Int)) : () do\n    match DistLink.decode_fire(frame) do\n      Err(_) -> ()\n      Ok((target_pid, reason)) ->\n        let prefix = mkey(l.node_id, target_pid)\n        let live = List.filter(Vault.all(h.downs), fn kv -> match kv do (k, _f) -> String.starts_with(k, prefix) end)\n        let refs = List.map(live, fn kv -> match kv do (k, _f) -> ref_of_key(k) end)\n        let _ = List.map(live, fn kv ->\n          match kv do\n            (k, f) ->\n              Vault.drop(h.downs, k)\n              f(reason)\n          end)\n        -- Remember whom we delivered to, so a resent copy is acked too.\n        let fkey = \"f\" ++ l.node_id ++ \"|\" ++ int_to_string(target_pid)\n        let all_refs = List.dedup(List.append(refs, Vault.get_or(h.fired, fkey, Nil)))\n        Vault.set(h.fired, fkey, all_refs)\n        discard(List.map(all_refs, fn r -> send(pid_of_int(l.cw), CtlWrite(DistLink.encode_ack(target_pid, r)))))\n    end\n  end\n\n  -- Every remote monitor on a node that just went Dead fires NodeDown here.\n  pfn monitors_node_down(h : CnHandle, node_id : String) : () do\n    let prefix = \"m\" ++ node_id ++ \"|\"\n    discard(List.map(Vault.all(h.downs), fn kv ->\n      match kv do\n        (k, f) ->\n          if String.starts_with(k, prefix) do\n            Vault.drop(h.downs, k)\n            f(DistLink.NodeDown)\n          else () end\n      end))\n  end\n\n  -- Resend every pending (fired, unacked) MONITOR_FIRE to its watcher's\n  -- current link, once a second.\n  pfn resend_fires(st : CnState, h : CnHandle, now : Int) : () do\n    if now < Vault.get_or(h.meta, \"resend_at\", 0) do () else\n      Vault.set(h.meta, \"resend_at\", now + 1000)\n      discard(List.map(dist_monitor_pending(), fn entry ->\n        match entry do\n          (target_pid, (watcher_node, (_ref, (rtag, rmsg)))) ->\n            match Map.get(st.links, watcher_node, Map.str_cmp) do\n              Some(l) -> discard(send(pid_of_int(l.cw), CtlWrite(DistLink.encode_fire(target_pid, DistLink.reason_of_tag(rtag, rmsg)))))\n              None -> ()\n            end\n        end))\n    end\n  end\n\n  pfn handshake_in(node, h : CnHandle, cfg : CnConfig, me : NodeIdentity.Identity, fd : Int) : Int do\n    match NetKernel.handshake_auth(fd, me, h_auth(h, cfg.auth), NetKernel.fresh_nonce(), Handshake.role_control(),\n                                   cfg.advertise, cfg.handshake_timeout_ms) do\n      Err(e) ->\n        tcp_close(fd)\n        -- The stop() wake-up connection says nothing and closes: not an attack.\n        if Vault.get(h.meta, \"stopped\") == None do security(h, HandshakeRejected(\"inbound\", e)) else () end\n        0\n      Ok(a) ->\n        let peer = a.identity\n        send(node, Accepted(fd, peer.node_id, peer.name, a.role, a.addr, peer.incarnation, a.cert))\n        1\n    end\n  end\n\n  @[diverges] pfn accept_loop(node, h : CnHandle, cfg : CnConfig, me : NodeIdentity.Identity, listen_fd : Int, meta : Vault(Int),\n                  not_before : Int) : Int do\n    match tcp_accept(listen_fd) do\n      Err(_) -> 0\n      Ok(fd) ->\n        if Vault.get(meta, \"stopped\") != None do\n          tcp_close(fd)\n          tcp_close(listen_fd)\n          0\n        else\n          let _ = task_spawn(fn _ -> handshake_in(node, h, cfg, me, fd))\n          if epoch_draining() && unix_time_ms() >= not_before do\n            -- Move to the new code epoch (see above); the listen socket stays open.\n            send(node, MoveAcceptor())\n            0\n          else accept_loop(node, h, cfg, me, listen_fd, meta, not_before) end\n        end\n    end\n  end\n\n  @[diverges] pfn tick_loop(node, h : CnHandle, files : Option(CertFiles), tick_ms : Int, not_before : Int) : Int do\n    sleep_ms(tick_ms)\n    if Vault.get(h.meta, \"stopped\") != None do\n      0\n    else\n      send(node, Tick(unix_time_ms()))\n      watch_cert_files(h, files)\n      if epoch_draining() && unix_time_ms() >= not_before do\n        -- Move to the new code epoch (see above).\n        send(node, MoveTicker())\n        0\n      else tick_loop(node, h, files, tick_ms, not_before) end\n    end\n  end\n\n  -- \u2500\u2500 the certificate files \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- How a replacement is triggered from outside (step 12b): the ticker\n  -- re-reads MARCH_NODE_CERT's file (and MARCH_NODE_KEY's) every\n  -- `cert_files.poll_ms` and, when either changed, replaces the certificate\n  -- through `replace_cert`. A file rather than a signal: SIGHUP is\n  -- Topology's reload and SIGUSR1 the scheduler's, and what renews\n  -- certificates in practice (a Kubernetes secret volume, cert-manager, a\n  -- Vault agent, a CI job copying files) rewrites the file and signals no\n  -- one. Each content is tried once: a refusal (a half-written file, or a\n  -- certificate for a new key whose key file is not there yet) is reported\n  -- as CertRefused and tried again when either file changes.\n\n  pfn read_trimmed(path : String) : String do\n    match File.read(path) do\n      Ok(t) -> String.trim(t)\n      Err(_) -> \"\"\n    end\n  end\n\n  pfn cert_files_text(f : CertFiles) : String do\n    read_trimmed(f.cert) ++ \"\\n\" ++ (if String.is_empty(f.key) do \"\" else read_trimmed(f.key) end)\n  end\n\n  pfn watch_cert_files(h : CnHandle, files : Option(CertFiles)) : () do\n    match files do\n      None -> ()\n      Some(f) ->\n        let now = unix_time_ms()\n        if now < Vault.get_or(h.meta, \"cert_poll_at\", 0) do () else\n          Vault.set(h.meta, \"cert_poll_at\", now + f.poll_ms)\n          let seen = cert_files_text(f)\n          if Vault.get(h.strs, \"cert_files\") == Some(seen) do () else\n            Vault.set(h.strs, \"cert_files\", seen)\n            let key = if String.is_empty(f.key) do \"\" else read_trimmed(f.key) end\n            discard(h_replace_cert(h, read_trimmed(f.cert), key))\n          end\n        end\n    end\n  end\n\n  -- \u2500\u2500 the capability \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- A running node is a `Cap(ClusterNode.Live)` (D35 of\n  -- specs/plans/2026-09-21-distributed-authority-and-deploys-plan.md), on the\n  -- model of `Cap(Session.Live)`: `start` mints it over the node's `CnHandle`\n  -- record with the real dictionary (`ops_of`), and every public operation\n  -- below dispatches through `cap_dict`. A test attaches its own dictionary\n  -- with `attach(io, ops)` -- membership, names and the data plane then come\n  -- from the test, with no sockets. `CnHandle` stays the dictionary's backing\n  -- value: the node actor, the readers and the Vault mirrors all still work on\n  -- it, and the Vault reads (`members`, `lookup`, `queue_for`, ...) cost what\n  -- they did plus one indirect call.\n  --\n  -- One field per operation; `global_pid` and `await_members` are derived\n  -- (from `node_id`/`creation` and from `members`). `node_id` is this node's\n  -- id; `next_id(key)` is a per-node counter (SessionAP numbers its sessions\n  -- with it).\n  type ClusterOps = {\n    node_id            : String,\n    stop               : () -> (),\n    subscribe          : (NodeEvent -> Unit) -> Int,\n    unsubscribe        : Int -> (),\n    members            : () -> List(NodeInfo),\n    all_members        : () -> List(Member),\n    addr_of            : String -> Option(String),\n    name_of            : String -> Option(String),\n    link_count         : () -> Int,\n    register           : String -> Int -> Result((), RegisterError),\n    unregister         : String -> (),\n    lookup             : String -> Option(GlobalPid.Pid),\n    registrant         : String -> Option(String),\n    names              : () -> List(String),\n    watch              : String -> (NameEvent -> Unit) -> Int,\n    unwatch            : Int -> (),\n    stale_bindings     : () -> Int,\n    creation           : () -> Int,\n    next_id            : String -> Int,\n    queue_for          : String -> Option((Pid(NodeQueue.WriterState), Int)),\n    session_queue_for  : String -> Option((Pid(NodeQueue.WriterState), Int)),\n    send_msg           : GlobalPid.Pid -> String -> List(Int) -> NodeQueue.Policy -> Result(Int, NodeQueue.EnqueueError),\n    route              : Int -> (NodeSend.Delivery -> Result((), String)) -> String,\n    route_type         : String -> (NodeSend.Delivery -> Result((), String)) -> String,\n    route_session      : Int -> (NodeSend.Delivery -> Result((), String)) -> String,\n    unroute            : String -> (),\n    on_peer_closed     : (String -> String -> Unit) -> Int,\n    off_peer_closed    : Int -> (),\n    on_delivery_failed : (Int -> String -> Unit) -> (),\n    on_session_failed  : Int -> (String -> String -> Unit) -> (),\n    off_session_failed : Int -> (),\n    monitor_remote     : GlobalPid.Pid -> (DistLink.DownReason -> Unit) -> Result(Int, String),\n    demonitor_remote   : GlobalPid.Pid -> Int -> (),\n    peer_cert          : String -> Option(NodeCert.Cert),\n    own_cert           : () -> Option(NodeCert.Cert),\n    frames_rejected    : () -> Int,\n    raw_refused        : () -> Int,\n    revoke             : String -> Result((), String),\n    revocations        : () -> List(NodeCert.Revocation),\n    replace_cert       : String -> String -> Result(NodeCert.Cert, String),\n    on_security_event  : (SecurityEvent -> Unit) -> Int,\n    off_security_event : Int -> (),\n    registry_synced    : () -> Bool,\n    rejoined_at        : () -> Option(Int),\n    handshake          : Int -> String -> Int -> Result(NetKernel.Authed, String)\n  }\n\n  proof cap Live with ClusterOps\n\n  doc \"\"\"\n  Attach a cluster dictionary. With `start`, the only way to obtain a\n  `Cap(ClusterNode.Live)`; this one is the test seam: a test builds `ops`\n  (usually `{ ClusterNode.ops_stub(id) with members: ..., subscribe: ... }`)\n  and hands the cap to code written against a real node.\n  \"\"\"\n  fn attach(io : Cap(IO), ops : ClusterOps) : Cap(ClusterNode.Live) do\n    cap_impl(mint_cap(io), ops)\n  end\n\n  pfn unsupported(op : String) do\n    panic(\"ClusterNode: this cluster dictionary does not provide `\" ++ op ++ \"`\")\n  end\n\n  doc \"\"\"\n  A dictionary for node [node_id] in which every operation panics, naming\n  itself. Override the fields a test uses with record update.\n  \"\"\"\n  fn ops_stub(node_id : String) : ClusterOps do\n    { node_id: node_id,\n      stop: fn _ -> unsupported(\"stop\"),\n      subscribe: fn _ -> unsupported(\"subscribe\"),\n      unsubscribe: fn _ -> unsupported(\"unsubscribe\"),\n      members: fn _ -> unsupported(\"members\"),\n      all_members: fn _ -> unsupported(\"all_members\"),\n      addr_of: fn _ -> unsupported(\"addr_of\"),\n      name_of: fn _ -> unsupported(\"name_of\"),\n      link_count: fn _ -> unsupported(\"link_count\"),\n      register: fn (_, _) -> unsupported(\"register\"),\n      unregister: fn _ -> unsupported(\"unregister\"),\n      lookup: fn _ -> unsupported(\"lookup\"),\n      registrant: fn _ -> unsupported(\"registrant\"),\n      names: fn _ -> unsupported(\"names\"),\n      watch: fn (_, _) -> unsupported(\"watch\"),\n      unwatch: fn _ -> unsupported(\"unwatch\"),\n      stale_bindings: fn _ -> unsupported(\"stale_bindings\"),\n      creation: fn _ -> unsupported(\"creation\"),\n      next_id: fn _ -> unsupported(\"next_id\"),\n      queue_for: fn _ -> unsupported(\"queue_for\"),\n      session_queue_for: fn _ -> unsupported(\"session_queue_for\"),\n      send_msg: fn (_, _, _, _) -> unsupported(\"send_msg\"),\n      route: fn (_, _) -> unsupported(\"route\"),\n      route_type: fn (_, _) -> unsupported(\"route_type\"),\n      route_session: fn (_, _) -> unsupported(\"route_session\"),\n      unroute: fn _ -> unsupported(\"unroute\"),\n      on_peer_closed: fn _ -> unsupported(\"on_peer_closed\"),\n      off_peer_closed: fn _ -> unsupported(\"off_peer_closed\"),\n      on_delivery_failed: fn _ -> unsupported(\"on_delivery_failed\"),\n      on_session_failed: fn (_, _) -> unsupported(\"on_session_failed\"),\n      off_session_failed: fn _ -> unsupported(\"off_session_failed\"),\n      monitor_remote: fn (_, _) -> unsupported(\"monitor_remote\"),\n      demonitor_remote: fn (_, _) -> unsupported(\"demonitor_remote\"),\n      peer_cert: fn _ -> unsupported(\"peer_cert\"),\n      own_cert: fn _ -> None,\n      frames_rejected: fn _ -> unsupported(\"frames_rejected\"),\n      raw_refused: fn _ -> unsupported(\"raw_refused\"),\n      revoke: fn _ -> unsupported(\"revoke\"),\n      revocations: fn _ -> unsupported(\"revocations\"),\n      replace_cert: fn (_, _) -> unsupported(\"replace_cert\"),\n      on_security_event: fn _ -> unsupported(\"on_security_event\"),\n      off_security_event: fn _ -> unsupported(\"off_security_event\"),\n      -- Not panics: Topology.place reads both, and a fake cluster is one\n      -- that has synced and that no peer remembers.\n      registry_synced: fn _ -> true,\n      rejoined_at: fn _ -> None,\n      handshake: fn (_, _, _) -> Err(\"ClusterNode: handshake is not supported by this capability\") }\n  end\n\n  -- The real dictionary: every operation over the node's backing record.\n  pfn ops_of(h : CnHandle) : ClusterOps do\n    { node_id: h.node_id,\n      stop: fn _ -> h_stop(h),\n      subscribe: fn f -> h_subscribe(h, f),\n      unsubscribe: fn id -> Vault.drop(h.subs, int_to_string(id)),\n      members: fn _ -> h_members(h),\n      all_members: fn _ -> List.map(Vault.all(h.members), fn kv -> match kv do (_k, m) -> m end),\n      addr_of: fn id -> h_addr_of(h, id),\n      name_of: fn id -> h_name_of(h, id),\n      link_count: fn _ -> Vault.get_or(h.meta, \"links\", 0),\n      register: fn (name, p) -> h_register(h, name, p),\n      unregister: fn name -> discard(send(node_pid(h), Unregister(name))),\n      lookup: fn name -> Vault.get(h.names, name),\n      registrant: fn name -> Vault.get(h.registrants, name),\n      names: fn _ -> Vault.keys(h.names),\n      watch: fn (name, f) -> h_watch(h, name, f),\n      unwatch: fn id -> h_unwatch(h, id),\n      stale_bindings: fn _ -> Vault.get_or(h.meta, \"stale_bindings\", 0),\n      creation: fn _ -> Vault.get_or(h.meta, \"creation\", 0),\n      next_id: fn key -> Vault.incr(h.meta, \"next_id#\" ++ key, 1),\n      queue_for: fn id -> h_raw_queue_for(h, id),\n      session_queue_for: fn id -> h_queue_for(h, id),\n      send_msg: fn (to, tag, payload, policy) -> h_send_msg(h, to, tag, payload, policy),\n      route: fn (pid, deliver) -> h_route(h, \"p\" ++ int_to_string(pid), deliver),\n      route_type: fn (tag, deliver) -> h_route(h, \"t\" ++ tag, deliver),\n      route_session: fn (pid, deliver) -> h_route(h, \"s\" ++ int_to_string(pid), deliver),\n      unroute: fn key -> Vault.drop(h.routes, key),\n      on_peer_closed: fn f -> h_on_peer_closed(h, f),\n      off_peer_closed: fn id -> Vault.drop(h.closes, int_to_string(id)),\n      on_delivery_failed: fn f -> Vault.set(h.failed, \"f\", f),\n      on_session_failed: fn (key, f) -> Vault.set(h.sfailed, int_to_string(key), f),\n      off_session_failed: fn key -> Vault.drop(h.sfailed, int_to_string(key)),\n      monitor_remote: fn (target, on_down) -> h_monitor_remote(h, target, on_down),\n      demonitor_remote: fn (target, r) -> Vault.drop(h.downs, mkey(target.node_id, target.local_pid) ++ int_to_string(r)),\n      peer_cert: fn id -> Vault.get(h.certs, id),\n      own_cert: fn _ -> h_own(h),\n      frames_rejected: fn _ -> Vault.get_or(h.meta, \"frames_rejected\", 0),\n      raw_refused: fn _ -> Vault.get_or(h.meta, \"raw_refused\", 0),\n      revoke: fn token -> h_revoke(h, token),\n      revocations: fn _ -> List.map(Vault.all(h.revs), fn kv -> match kv do (_k, r) -> r end),\n      replace_cert: fn (cert_text, key_hex) -> h_replace_cert(h, cert_text, key_hex),\n      on_security_event: fn f -> h_on_security_event(h, f),\n      off_security_event: fn id -> Vault.drop(h.sec, int_to_string(id)),\n      registry_synced: fn _ -> Vault.get_or(h.meta, \"reg_synced\", 0) != 0,\n      rejoined_at: fn _ -> Vault.get(h.meta, \"rejoined_at\"),\n      handshake: fn (fd, role, timeout_ms) -> h_handshake(h, fd, role, timeout_ms) }\n  end\n\n  -- The cluster link's handshake on a connection that is not a link (the\n  -- control API's candidate-to-candidate verbs): this node's identity and\n  -- credentials as of now, so a replaced certificate and new revocations\n  -- apply, exactly as on a link.\n  pfn h_handshake(h : CnHandle, fd : Int, role : String, timeout_ms : Int) : Result(NetKernel.Authed, String) do\n    let me = NodeIdentity.make(h.name, \"pk-\" ++ h.name, Vault.get_or(h.meta, \"creation\", 0))\n    NetKernel.handshake_auth(fd, me, h_auth(h, ClusterAuth.Secret(\"\")), NetKernel.fresh_nonce(), role,\n                             h.advertise, timeout_ms)\n  end\n\n  pfn no_cluster() do\n    panic(\"ClusterNode: no cluster dictionary attached to this capability\")\n  end\n\n  pfn ops(c : Cap(ClusterNode.Live)) : ClusterOps do\n    match cap_dict(c) do\n      Some(d) -> d\n      None -> no_cluster()\n    end\n  end\n\n  -- \u2500\u2500 the node behind the real dictionary \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn h_stop(h : CnHandle) : () do\n    Vault.set(h.meta, \"stopped\", 1)\n    send(node_pid(h), Shutdown())\n    -- The loopback link goes with the node: `queue_for(own id)` answers None\n    -- from here on, and its writer drops its sink (behind any frame already\n    -- queued, which `deliver_loopback` then refuses as stopped).\n    match loopback(h) do\n      Some(q) ->\n        Vault.drop(h.qs, \"loop\")\n        NodeQueue.close_fd(q)\n      None -> ()\n    end\n    -- The loopback is a connection too, and it has just ended: tell every\n    -- session party (on_peer_closed) that this node's peers are gone, as a\n    -- link to another node does when it drops (data_closed). Without it, a\n    -- party whose peers are on this node waited for ever for frames the\n    -- closed loopback refused, and its non-daemon runner kept the process\n    -- from exiting (specs/progress/2026-10-07-cluster-stop-loopback-exit-hang.md).\n    discard(List.map(Vault.all(h.closes), fn kv -> match kv do (_k, f) -> f(h.node_id, \"node stopped\") end))\n    -- Wake the acceptor, parked in tcp_accept, with a connection of our\n    -- own: it sees the stop flag and returns. (Closing the listen socket\n    -- under a parked accept does not wake it on every platform.)\n    match split_addr(h.advertise) do\n      Some((_host, port)) ->\n        match Socket.connect_timeout(\"127.0.0.1\", port, 500) do\n          Ok(fd) -> tcp_close(fd)\n          Err(_) -> ()\n        end\n      None -> ()\n    end\n    -- The acceptor closes the listen socket itself once it sees the flag:\n    -- closing it here could land between the wake-up connection and the\n    -- scheduler delivering the acceptor's readiness, and a close drops the\n    -- fd's kqueue/epoll registration -- the acceptor then never wakes and\n    -- the process never exits (seen 2 in 8 runs of cluster_stall).\n  end\n\n  pfn h_subscribe(h : CnHandle, on_event : NodeEvent -> Unit) : Int do\n    let id = Vault.incr(h.meta, \"next_sub\", 1)\n    Vault.set(h.subs, int_to_string(id), on_event)\n    let _ = List.map(h_members(h), fn i -> on_event(NodeUp(i)))\n    id\n  end\n\n  pfn h_members(h : CnHandle) : List(NodeInfo) do\n    List.filter_map(Vault.all(h.members), fn kv ->\n      match kv do\n        (_k, m) ->\n          if m.node_id == h.node_id do None\n          else\n            match m.status do\n              Alive -> Some(info_of(m))\n              _ -> None\n            end\n          end\n      end)\n  end\n\n  pfn h_addr_of(h : CnHandle, node_id : String) : Option(String) do\n    match Vault.get(h.members, node_id) do\n      Some(m) -> if String.is_empty(m.addr) do None else Some(m.addr) end\n      None -> None\n    end\n  end\n\n  pfn h_name_of(h : CnHandle, node_id : String) : Option(String) do\n    match Vault.get(h.members, node_id) do\n      Some(m) -> Some(m.name)\n      None -> None\n    end\n  end\n\n  pfn watch_sep() : String do \"#watch#\" end\n\n  doc \"\"\"\n  The synchronous half of `register`: decide, in the caller, whether local\n  pid [p] may take [name] on node [node_id] (at [creation]). [names] is the\n  node's mirrored view; [claims] holds the registrations sent to the node\n  actor but not yet processed there (name -> pid). The claim is taken first\n  (`Vault.put_new`, atomic), then the view is checked, and the node actor\n  mirrors a binding before releasing its claim (`release_claim`), so two\n  concurrent registrations of one name by different pids cannot both get\n  `Ok`. The same pid registering again is allowed. On `Ok` the caller owns\n  the claim and must send the `Register` that releases it.\n  \"\"\"\n  @[diverges] fn reserve(names : Vault(GlobalPid.Pid), claims : Vault(Int), node_id : String, creation : Int,\n             name : String, p : Int) : Result((), RegisterError) do\n    let claimed = if Vault.put_new(claims, name, p) do Ok(true)\n      else\n        match Vault.get(claims, name) do\n          Some(q) -> if q == p do Ok(false) else Err(q) end\n          None -> Err(-1)   -- released between the two reads: retry\n        end\n      end\n    match claimed do\n      Err(q) ->\n        if q < 0 do reserve(names, claims, node_id, creation, name, p)\n        else Err(Taken(GlobalPid.make(node_id, q, creation))) end\n      Ok(fresh) ->\n        let taken = match Vault.get(names, name) do\n          Some(holder) -> if holder.node_id == node_id && holder.local_pid == p do None else Some(holder) end\n          None -> None\n        end\n        match taken do\n          Some(holder) ->\n            if fresh do release_claim(claims, name, p) else () end\n            Err(Taken(holder))\n          None -> Ok(())\n        end\n    end\n  end\n\n  doc \"Drop [name]'s pending claim (see `reserve`) if pid [p] holds it.\"\n  fn release_claim(claims : Vault(Int), name : String, p : Int) : () do\n    match Vault.get(claims, name) do\n      Some(q) -> if q == p do Vault.drop(claims, name) else () end\n      None -> ()\n    end\n  end\n\n  pfn h_register(h : CnHandle, name : String, p : Int) : Result((), RegisterError) do\n    if Vault.get(h.meta, \"stopped\") != None do\n      Err(Stopped)\n    else\n      match reserve(h.names, h.claims, h.node_id, Vault.get_or(h.meta, \"creation\", 0), name, p) do\n        Err(e) -> Err(e)\n        Ok(_) ->\n          let w = spawn(RegWatch)\n          send(w, WatchPid(h.pid, p))\n          let _ = monitor(w, pid_of_int(p))\n          send(node_pid(h), Register(name, p, pid_to_int(w)))\n          Ok(())\n      end\n    end\n  end\n\n  pfn h_watch(h : CnHandle, name : String, on_event : NameEvent -> Unit) : Int do\n    let id = Vault.incr(h.meta, \"next_watch\", 1)\n    Vault.set(h.watches, name ++ watch_sep() ++ int_to_string(id), on_event)\n    match Vault.get(h.names, name) do\n      Some(p) -> on_event(Bound(name, p))\n      None -> ()\n    end\n    id\n  end\n\n  pfn h_unwatch(h : CnHandle, id : Int) : () do\n    let suffix = watch_sep() ++ int_to_string(id)\n    discard(List.map(Vault.keys(h.watches), fn k ->\n      if String.ends_with(k, suffix) do Vault.drop(h.watches, k) else () end))\n  end\n\n  -- The raw queue (`queue_for`, what `Node.enqueue` sends through): None,\n  -- counted and reported, when raw sends to [node_id] are refused.\n  pfn h_raw_queue_for(h : CnHandle, node_id : String) : Option((Pid(NodeQueue.WriterState), Int)) do\n    if h_raw_ok(h, node_id) do h_queue_for(h, node_id)\n    else\n      note_raw_refused(h, node_id, \"outbound queue\")\n      None\n    end\n  end\n\n  pfn h_queue_for(h : CnHandle, node_id : String) : Option((Pid(NodeQueue.WriterState), Int)) do\n    if node_id == h.node_id do loopback(h) else\n    match Vault.get(h.links, node_id) do\n      None -> None\n      Some(l) ->\n        -- A connection whose data reader has ended is no route, though the\n        -- node actor has not dropped it yet: a session party linking to it\n        -- would subscribe to its close after the close was told\n        -- (specs/progress/2026-10-15-session-links-dead-connection.md).\n        if Vault.get(h.meta, data_closed_key(l)) != None do None else\n        match Vault.get(h.qs, \"q\" ++ int_to_string(l.cfd)) do\n          Some(w) -> Some((pid_of_int(w), l.dfd))\n          None -> None\n        end end\n    end end\n  end\n\n  -- The LOOPBACK link: a node's queue to itself (made once, at `start`, so\n  -- every sender to this node shares one queue and one order). Its writer\n  -- hands each frame to `deliver_loopback` instead of a socket, and credit\n  -- is bypassed: there is no peer to grant it. Two roles of one session on\n  -- one node, and an initiator inviting its own node's offer, go through it\n  -- (distributed-deploys plan II.3).\n  pfn loopback(h : CnHandle) : Option((Pid(NodeQueue.WriterState), Int)) do\n    match Vault.get(h.qs, \"loop\") do\n      Some(w) -> Some((pid_of_int(w), Vault.get_or(h.meta, \"loop_fd\", -1)))\n      None -> None\n    end\n  end\n\n  -- An ACTOR_MSG this node sent itself: routed as the data reader routes one\n  -- from a peer; a failure goes to the DELIVERY_FAILED handler directly.\n  -- Once the node is stopped nothing is routed: a frame queued before\n  -- `stop` is answered \"node stopped\".\n  pfn deliver_loopback(h : CnHandle, frame : Bytes) : () do\n    match NetFrame.decode(Bytes.to_list(frame)) do\n      None -> ()\n      Some((body, _)) ->\n        match NodeSend.decode_msg(body) do\n          Err(_) -> ()\n          Ok(d0) ->\n            let d = { d0 with from_node: h.node_id }\n            -- A negative origin: the loopback, whose failures go to this\n            -- node's own handler (see `delivery_failed_hook`).\n            delivery_origin_set(0 - 1, d.seq)\n            let outcome = if Vault.get(h.meta, \"stopped\") != None do Err(\"node stopped\")\n            else if d.to_creation != Vault.get_or(h.meta, \"creation\", 0) do\n              Err(\"stale creation \" ++ int_to_string(d.to_creation) ++ \", node is at \" ++ int_to_string(Vault.get_or(h.meta, \"creation\", 0)))\n            else deliver_local(h, d) end end\n            delivery_origin_clear()\n            match outcome do\n              Ok(_) -> ()\n              Err(reason) ->\n                match Vault.get(h.failed, \"f\") do\n                  Some(f) -> f(d.seq, reason)\n                  None -> ()\n                end\n            end\n        end\n    end\n  end\n\n  -- A raw send (not session traffic) to a peer where raw sends are refused\n  -- is Err(NotAuthorized), counted and reported, and never queued.\n  pfn h_send_msg(h : CnHandle, to : GlobalPid.Pid, type_tag : String, payload : List(Int),\n                 policy : NodeQueue.Policy) : Result(Int, NodeQueue.EnqueueError) do\n    if is_session_tag(type_tag) == false && h_raw_ok(h, to.node_id) == false do\n      note_raw_refused(h, to.node_id, \"outbound \" ++ type_tag)\n      Err(NodeQueue.NotAuthorized)\n    else\n    match h_queue_for(h, to.node_id) do\n      None -> Err(NodeQueue.NoConnection)\n      Some(q) ->\n        let seq = Vault.incr(h.meta, \"send_seq\", 1)\n        match NodeQueue.cast(q, seq, to, type_tag, payload, policy) do\n          Ok(_) -> Ok(seq)\n          Err(e) -> Err(e)\n        end\n    end end\n  end\n\n  pfn h_route(h : CnHandle, k : String, deliver : NodeSend.Delivery -> Result((), String)) : String do\n    Vault.set(h.routes, k, deliver)\n    k\n  end\n\n  pfn h_on_peer_closed(h : CnHandle, f : String -> String -> Unit) : Int do\n    let id = Vault.incr(h.meta, \"next_close\", 1)\n    Vault.set(h.closes, int_to_string(id), f)\n    id\n  end\n\n  pfn live_revoked(revs : Vault(NodeCert.Revocation), c : NodeCert.Cert) : Bool do\n    NodeCert.is_revoked(c, List.map(Vault.all(revs), fn kv -> match kv do (_k, r) -> r end))\n  end\n\n  pfn with_live_revocations(cfg : CnConfig, revs : Vault(NodeCert.Revocation)) : CnConfig do\n    match cfg.auth do\n      ClusterAuth.Certified(cr) ->\n        let inner = cr.revoked\n        let checked = { cr with revoked: fn c -> inner(c) || live_revoked(revs, c) }\n        { cfg with auth: ClusterAuth.Certified(checked) }\n      ClusterAuth.Secret(_) -> cfg\n    end\n  end\n\n  pfn h_revoke(h : CnHandle, token : String) : Result((), String) do\n    if Bytes.is_empty(h.op_pub) do Err(\"cluster_node: this node runs in shared-secret mode; revocations need certificate mode\")\n    else\n      match NodeCert.revocation_from_text(token) do\n        Err(e) -> Err(\"cluster_node: \" ++ e)\n        Ok(r) ->\n          match NodeCert.verify_revocation(r, h.op_pub) do\n            Err(e) -> Err(\"cluster_node: \" ++ e)\n            Ok(_) ->\n              send(node_pid(h), Revoke(r))\n              Ok(())\n          end\n      end\n    end\n  end\n\n  -- `replace_cert`: check the new certificate (and key) here, in the caller,\n  -- then make it this node's at once for handshakes and `own_cert`; the node\n  -- actor then takes it for dials and tells every linked peer (ReplaceCert).\n  -- Reported either way (CertReplaced / CertRefused). The certificate and key\n  -- already in use are a no-op, reported as nothing: a certificate the\n  -- control plane delivered and wrote back to the watched file comes round\n  -- again that way (step 12b).\n  pfn h_replace_cert(h : CnHandle, cert_text : String, key_hex : String) : Result(NodeCert.Cert, String) do\n    match replace_checked(h, cert_text, key_hex) do\n      Err(e) ->\n        security(h, CertRefused(h.node_id, e))\n        Err(e)\n      Ok((cr, signed, sk)) ->\n        if signed.body == cr.signed.body && Bytes.to_hex(sk) == Bytes.to_hex(cr.secret_key) do Ok(signed.cert)\n        else\n          Vault.set(h.auth, \"a\", ClusterAuth.Certified({ cr with signed: signed, secret_key: sk }))\n          send(node_pid(h), ReplaceCert(signed, sk))\n          security(h, CertReplaced(h.node_id, signed.cert.serial))\n          Ok(signed.cert)\n        end\n    end\n  end\n\n  -- The current credentials, and the new certificate and key once they\n  -- admit this node: the operator's signature, unexpired, naming this node\n  -- and the key, not revoked, and not issued before the certificate in use\n  -- (`NodeCert.supersedes`: a replayed, superseded certificate is refused,\n  -- across restarts too, since the node starts on the certificate it last\n  -- took). [key_hex] \"\" keeps the current key.\n  pfn replace_checked(h : CnHandle, cert_text : String, key_hex : String)\n      : Result((NodeCert.Credentials, NodeCert.Signed, Bytes), String) do\n    let cur = match h_auth(h, ClusterAuth.Secret(\"\")) do\n      ClusterAuth.Certified(cr) -> Some(cr)\n      ClusterAuth.Secret(_) -> None\n    end\n    match cur do\n      None -> Err(\"cluster_node: this node runs in shared-secret mode; replace_cert needs certificate mode\")\n      Some(cr) ->\n        if Vault.get(h.meta, \"stopped\") != None do Err(\"cluster_node: the node is stopped\")\n        else\n          let kh = String.trim(key_hex)\n          let new_key = not(String.is_empty(kh))\n          let sk_r = if new_key do NodeCert.key_from_hex(kh, 64) else Ok(cr.secret_key) end\n          match (sk_r, NodeCert.from_text(cert_text)) do\n            (Err(e), _) -> Err(\"cluster_node: the new key: \" ++ e)\n            (_, Err(e)) -> Err(\"cluster_node: the new certificate: \" ++ e)\n            (Ok(sk), Ok(signed)) ->\n              match NodeCert.verify(signed, h.op_pub, unix_time_ms() / 1000) do\n                Err(e) -> Err(\"cluster_node: the new certificate: \" ++ e)\n                Ok(c) ->\n                  if NodeCert.node_name(c.node) != h.name do\n                    Err(\"cluster_node: the new certificate names \" ++ c.node ++ \", but this node is \" ++ h.name)\n                  else if c.pubkey != Bytes.to_hex(NodeCert.public_key(sk)) do\n                    Err(\"cluster_node: the new certificate does not name \" ++ (if new_key do \"the new key\" else \"this node's key\" end))\n                  else if cr.revoked(c) do\n                    Err(\"cluster_node: the new certificate is revoked\")\n                  else\n                    match NodeCert.order_problem(c, cr.signed.cert) do\n                      Some(why) -> Err(\"cluster_node: the new certificate: \" ++ why)\n                      None ->\n                        let out = Ok((cr, signed, sk))\n                        out\n                    end\n                  end end end\n              end\n          end\n        end\n    end\n  end\n\n  pfn on_bad_frame(h : CnHandle, fd : Int, n : Int) : () do\n    match List.find(Vault.all(h.links), fn kv -> match kv do (_k, l) -> l.cfd == fd || l.dfd == fd end) do\n      Some((id, _l)) ->\n        let _ = Vault.incr(h.meta, \"frames_rejected\", 1)\n        security(h, FrameRejected(id, n))\n      None -> ()\n    end\n  end\n\n  pfn h_on_security_event(h : CnHandle, f : SecurityEvent -> Unit) : Int do\n    let id = Vault.incr(h.meta, \"next_sec\", 1)\n    Vault.set(h.sec, int_to_string(id), f)\n    id\n  end\n\n  pfn h_monitor_remote(h : CnHandle, target : GlobalPid.Pid, on_down : DistLink.DownReason -> Unit) : Result(Int, String) do\n    match Vault.get(h.links, target.node_id) do\n      None -> Err(\"cluster_node: no link to \" ++ target.node_id)\n      Some(l) ->\n        let r = Vault.incr(h.meta, \"next_monitor\", 1)\n        Vault.set(h.downs, mkey(target.node_id, target.local_pid) ++ int_to_string(r), on_down)\n        send(pid_of_int(l.cw), CtlWrite(DistLink.encode_req(h.node_id, r, target.local_pid)))\n        Ok(r)\n    end\n  end\n\n  -- \u2500\u2500 the API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Start a node: listen on `cfg.listen_port`, begin SWIM, dial the seeds.\n  Returns at once -- a node that reaches no seed runs as a cluster of one\n  and keeps redialling them (use `subscribe` or `await_members` to wait for\n  peers). Err only if the listen socket cannot be opened. The node is a\n  `Cap(ClusterNode.Live)` minted from [io]; pass it on to everything that\n  uses the cluster.\n  \"\"\"\n  fn start(io : Cap(IO), cfg : CnConfig) : Result(Cap(ClusterNode.Live), String) do\n    match tcp_listen(cfg.listen_port) do\n      Err(e) -> Err(\"cluster_node: listen on \" ++ int_to_string(cfg.listen_port) ++ \": \" ++ e)\n      Ok(listen_fd) ->\n        let node = spawn(ClusterNodeActor)\n        -- The node's Vaults hold its routes, names, membership and its\n        -- `stopped` flag: Cap(ClusterNode.Live) is meant to be the only way\n        -- in (D35). A Vault name is a global handle anyone with IO.Mut can\n        -- `Vault.whereis`, so the name carries 128 random bits; name + pid\n        -- alone was found by a scan over the pid range.\n        let tag = cfg.name ++ \".\" ++ int_to_string(pid_to_int(node)) ++ \".\" ++ Crypto.random_hex(16)\n        let h = { pid: pid_to_int(node), name: cfg.name, node_id: node_id_of(cfg.name), advertise: cfg.advertise,\n                  members: Vault.new(\"cluster_node_members_\" ++ tag),\n                  names: Vault.new(\"cluster_node_names_\" ++ tag),\n                  claims: Vault.new(\"cluster_node_claims_\" ++ tag),\n                  watches: Vault.new(\"cluster_node_watches_\" ++ tag),\n                  links: Vault.new(\"cluster_node_links_\" ++ tag),\n                  qs: Vault.new(\"cluster_node_qs_\" ++ tag),\n                  causes: Vault.new(\"cluster_node_causes_\" ++ tag),\n                  routes: Vault.new(\"cluster_node_routes_\" ++ tag),\n                  closes: Vault.new(\"cluster_node_closes_\" ++ tag),\n                  downs: Vault.new(\"cluster_node_downs_\" ++ tag),\n                  fired: Vault.new(\"cluster_node_fired_\" ++ tag),\n                  failed: Vault.new(\"cluster_node_failed_\" ++ tag),\n                  sfailed: Vault.new(\"cluster_node_sfailed_\" ++ tag),\n                  certs: Vault.new(\"cluster_node_certs_\" ++ tag),\n                  sec: Vault.new(\"cluster_node_sec_\" ++ tag),\n                  revs: Vault.new(\"cluster_node_revs_\" ++ tag),\n                  registrants: Vault.new(\"cluster_node_registrants_\" ++ tag),\n                  op_pub: match operator_key(cfg) do\n                    Some(k) -> k\n                    None -> Bytes.empty()\n                  end,\n                  auth: Vault.new(\"cluster_node_auth_\" ++ tag),\n                  strs: Vault.new(\"cluster_node_strs_\" ++ tag),\n                  subs: Vault.new(\"cluster_node_subs_\" ++ tag),\n                  meta: Vault.new(\"cluster_node_meta_\" ++ tag) }\n        Vault.set(h.meta, \"listen_fd\", listen_fd)\n        Vault.set(h.meta, \"creation\", cfg.creation)\n        delivery_failed_watch(fn (conn, seq, reason) -> delivery_failed_hook(h, conn, seq, reason))\n        match NodeQueue.start_local(fn frame -> deliver_loopback(h, frame)) do\n          (w, fd) ->\n            Vault.set(h.qs, \"loop\", pid_to_int(w))\n            Vault.set(h.meta, \"loop_fd\", fd)\n        end\n        -- The handshake's revocation check reads this node's live list.\n        let cfg = with_live_revocations(cfg, h.revs)\n        -- This node's credentials as of now: every handshake reads them\n        -- here, so a replacement (`replace_cert`) applies to the next one.\n        Vault.set(h.auth, \"a\", cfg.auth)\n        match cfg.cert_files do\n          Some(f) -> Vault.set(h.strs, \"cert_files\", cert_files_text(f))\n          None -> ()\n        end\n        let st0 = core_new(cfg, cfg.creation)\n        mirror(st0, h)\n        send(node, Boot(st0, h))\n        let me = NodeIdentity.make(cfg.name, \"pk-\" ++ cfg.name, cfg.creation)\n        let meta = h.meta\n        let _ = task_spawn(fn _ -> accept_loop(node, h, cfg, me, listen_fd, meta, 0))\n        let _ = task_spawn(fn _ -> tick_loop(node, h, cfg.cert_files, cfg.tick_ms, 0))\n        -- Frames that fail their MAC on one of this node's links: counted\n        -- and reported by peer (the hook is process-wide; other nodes'\n        -- fds are not in our links).\n        let _ = NetKernel.on_frame_rejected(fn (fd, n) -> on_bad_frame(h, fd, n))\n        Ok(attach(io, ops_of(h)))\n    end\n  end\n\n  doc \"Stop the node: close every link (the loopback too) and the listener, stop the ticker.\"\n  fn stop(c : Cap(ClusterNode.Live)) : () do\n    let d = ops(c)\n    d.stop(())\n  end\n\n  doc \"This node's id.\"\n  fn node_id(c : Cap(ClusterNode.Live)) : String do\n    let d = ops(c)\n    d.node_id\n  end\n\n  doc \"\"\"\n  Call [on_event] (in the node actor's turn: it must only `send`) for every\n  membership change. A subscriber added late gets `NodeUp` at once for\n  every member currently Alive. Returns an id for `unsubscribe`.\n  \"\"\"\n  fn subscribe(c : Cap(ClusterNode.Live), on_event : NodeEvent -> Unit) : Int do\n    let d = ops(c)\n    d.subscribe(on_event)\n  end\n\n  doc \"Remove the `subscribe` callback with id [id]; an unknown id is a no-op.\"\n  fn unsubscribe(c : Cap(ClusterNode.Live), id : Int) : () do\n    let d = ops(c)\n    d.unsubscribe(id)\n  end\n\n  doc \"Every other node this node knows as Alive.\"\n  fn members(c : Cap(ClusterNode.Live)) : List(NodeInfo) do\n    let d = ops(c)\n    d.members(())\n  end\n\n  doc \"Every member this node knows of, in any status, itself included.\"\n  fn all_members(c : Cap(ClusterNode.Live)) : List(Member) do\n    let d = ops(c)\n    d.all_members(())\n  end\n\n  doc \"The advertised address of [node_id], if this node has heard it.\"\n  fn addr_of(c : Cap(ClusterNode.Live), node_id : String) : Option(String) do\n    let d = ops(c)\n    d.addr_of(node_id)\n  end\n\n  doc \"The name of [node_id], if known.\"\n  fn name_of(c : Cap(ClusterNode.Live), node_id : String) : Option(String) do\n    let d = ops(c)\n    d.name_of(node_id)\n  end\n\n  doc \"How many peers this node currently has a connection pair to.\"\n  fn link_count(c : Cap(ClusterNode.Live)) : Int do\n    let d = ops(c)\n    d.link_count(())\n  end\n\n  doc \"\"\"\n  A per-node counter: the next value (from 1) under [key]. Code that needs\n  ids unique on this node (SessionAP's session numbers) draws them here.\n  \"\"\"\n  fn next_id(c : Cap(ClusterNode.Live), key : String) : Int do\n    let d = ops(c)\n    d.next_id(key)\n  end\n\n  -- \u2500\u2500 names \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Register [name] -> [pid] (a process on this node) cluster-wide. Refused\n  with `Taken(holder)` if another holder's binding is visible here, or\n  another local pid's registration of [name] is still pending (so two\n  concurrent local registrations of one name cannot both succeed). `Ok`\n  means the binding is made here and pushed to every peer; it is not a lock\n  -- a node on the far side of a partition can hold the same name, and after\n  the heal one binding wins everywhere (watch the name to hear `Lost`). The\n  check is against this node's view; if another binding reaches the node\n  first, the registration is refused there and the name's watchers get\n  `Lost(name, holder)`. A process already dead by then is not registered.\n  The process is monitored: its death unregisters the name.\n  \"\"\"\n  fn register(c : Cap(ClusterNode.Live), name : String, pid) : Result((), RegisterError) do\n    let d = ops(c)\n    d.register(name, pid_to_int(pid))\n  end\n\n  doc \"This node's creation (its incarnation number, part of every global pid it issues).\"\n  fn creation(c : Cap(ClusterNode.Live)) : Int do\n    let d = ops(c)\n    d.creation(())\n  end\n\n  doc \"A global pid for the local actor [pid] on this node (to hand to a peer as a reply address).\"\n  fn global_pid(c : Cap(ClusterNode.Live), pid : Int) : GlobalPid.Pid do\n    let d = ops(c)\n    GlobalPid.make(d.node_id, pid, d.creation(()))\n  end\n\n  doc \"Unregister [name], if this node holds it. A name another node holds is left alone.\"\n  fn unregister(c : Cap(ClusterNode.Live), name : String) : () do\n    let d = ops(c)\n    d.unregister(name)\n  end\n\n  doc \"\"\"\n  The process bound to [name] cluster-wide, as this node sees it (a Vault\n  read). In certificate mode a binding is hidden unless a raw send to its\n  holder would be allowed (both certificates carry raw_send; this node's own\n  bindings and the coordination namespaces `reference_namespaces()` always\n  show): a name you cannot raw-send to is not a reference you should hold.\n  \"\"\"\n  fn lookup(c : Cap(ClusterNode.Live), name : String) : Option(GlobalPid.Pid) do\n    let d = ops(c)\n    d.lookup(name)\n  end\n\n  doc \"\"\"\n  Who registered [name]: the certificate identity (URI) of the registering\n  node as this node recorded it, \"\" when unknown (shared-secret mode, or a\n  relayed binding whose holder this node has not verified). None when no\n  present binding exists. Not hidden the way `lookup` is.\n  \"\"\"\n  fn registrant(c : Cap(ClusterNode.Live), name : String) : Option(String) do\n    let d = ops(c)\n    d.registrant(name)\n  end\n\n  doc \"Every name with a visible binding here.\"\n  fn names(c : Cap(ClusterNode.Live)) : List(String) do\n    let d = ops(c)\n    d.names(())\n  end\n\n  doc \"\"\"\n  Call [on_event] (in the node actor's turn: it must only `send`) on every\n  change to [name]'s visible binding: `Bound(name, pid)`, `Unbound(name)`,\n  or `Lost(name, winner)` when a binding made on THIS node is superseded by\n  another holder's (after a partition heals, say). A watcher added while the\n  name is bound gets `Bound` at once. Returns an id for `unwatch`.\n  \"\"\"\n  fn watch(c : Cap(ClusterNode.Live), name : String, on_event : NameEvent -> Unit) : Int do\n    let d = ops(c)\n    d.watch(name, on_event)\n  end\n\n  doc \"Remove the `watch` callback with id [id] (whatever name it watched); an unknown id is a no-op.\"\n  fn unwatch(c : Cap(ClusterNode.Live), id : Int) : () do\n    let d = ops(c)\n    d.unwatch(id)\n  end\n\n  doc \"\"\"\n  Has this node merged a peer's registry replica yet (the sync a peer sends\n  when a link comes up)? Always true for a node started with no seeds: it\n  has no one to wait for. Until then this node's view of the names (and of\n  Topology's eligibility markers) is its own alone.\n  \"\"\"\n  fn registry_synced(c : Cap(ClusterNode.Live)) : Bool do\n    let d = ops(c)\n    d.registry_synced(())\n  end\n\n  doc \"\"\"\n  When (unix ms) a peer last showed this node as rejoining: its member view\n  held this node at an earlier creation (a restart) or Dead (a restart that\n  kept its creation, a heal). That peer reports the node's return as\n  `NodeRejoined` and lets it settle before counting it; None if no peer has.\n  \"\"\"\n  fn rejoined_at(c : Cap(ClusterNode.Live)) : Option(Int) do\n    let d = ops(c)\n    d.rejoined_at(())\n  end\n\n  doc \"How many present bindings of this node's from an earlier creation the replica holds (0 once retired).\"\n  fn stale_bindings(c : Cap(ClusterNode.Live)) : Int do\n    let d = ops(c)\n    d.stale_bindings(())\n  end\n\n  doc \"\"\"\n  A one-line description of name event [ev], naming the holder by node id:\n  `\"<name> bound to <node_id>\"`, `\"<name> unbound\"` or\n  `\"<name> lost to <node_id>\"`.\n  \"\"\"\n  fn name_event_text(ev : NameEvent) : String do\n    match ev do\n      Bound(n, p) -> n ++ \" bound to \" ++ p.node_id\n      Unbound(n) -> n ++ \" unbound\"\n      Lost(n, p) -> n ++ \" lost to \" ++ p.node_id\n    end\n  end\n\n  -- \u2500\u2500 the shared data plane \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  The outbound queue of the data connection to [node_id], for\n  `Node.enqueue(q, to, msg, policy)` (the typed send) or `NodeQueue.cast`.\n  Every write to a data socket goes through this one writer, so this is the\n  only way to send on it: `Node.send(peer, ...)` writes the socket directly\n  and would interleave with the queue.\n\n  This is a RAW send path: in certificate mode it is None (counted in\n  `raw_refused`, reported as `RawSendRefused`) unless this node's and the\n  peer's certificates both carry `raw_send`. The peer refuses a raw frame\n  it receives from a node without raw_send in any case.\n  \"\"\"\n  fn queue_for(c : Cap(ClusterNode.Live), node_id : String) : Option((Pid(NodeQueue.WriterState), Int)) do\n    let d = ops(c)\n    d.queue_for(node_id)\n  end\n\n  doc \"\"\"\n  `queue_for` for SESSION traffic (SessionNode's cluster links): never refused\n  for want of `raw_send`, since what it carries is checked at the receiver\n  (session frames reach only session routes). Not for raw sends: a raw frame\n  sent through it is refused by a receiver that would refuse it anyway.\n  \"\"\"\n  fn session_queue_for(c : Cap(ClusterNode.Live), node_id : String) : Option((Pid(NodeQueue.WriterState), Int)) do\n    let d = ops(c)\n    d.session_queue_for(node_id)\n  end\n\n  doc \"\"\"\n  Send [payload] (an encoded message of type [type_tag]) to the remote\n  process [to] through its node's data queue. `Ok(seq)` means admitted, not\n  delivered: a delivery failure comes back as DELIVERY_FAILED (see\n  `on_delivery_failed`). `Err(NoConnection)` when this node has no link to\n  [to]'s node.\n\n  In certificate mode a send whose [type_tag] is not session traffic\n  (`session_tags()`) is a raw send: `Err(NotAuthorized)` (counted in\n  `raw_refused`, reported as `RawSendRefused`) unless this node's and the\n  peer's certificates both carry `raw_send`. Sends to this node itself are\n  never refused.\n  \"\"\"\n  fn send_msg(c : Cap(ClusterNode.Live), to : GlobalPid.Pid, type_tag : String, payload : List(Int),\n              policy : NodeQueue.Policy) : Result(Int, NodeQueue.EnqueueError) do\n    let d = ops(c)\n    d.send_msg(to, type_tag, payload, policy)\n  end\n\n  doc \"\"\"\n  Deliver every ACTOR_MSG addressed to local pid [pid] to [deliver], called\n  in the data reader's task (it should only `send`). Its `Err(reason)` goes\n  back to the sender as DELIVERY_FAILED. Returns the key for `unroute`.\n\n  A route is a raw receiver: in certificate mode a delivery from a peer is\n  refused before it reaches [deliver] (DELIVERY_FAILED to the sender, counted\n  in `raw_refused`, reported as `RawSendRefused`) unless this node's and the\n  sender's certificates both carry `raw_send`.\n  \"\"\"\n  fn route(c : Cap(ClusterNode.Live), pid : Int, deliver : NodeSend.Delivery -> Result((), String)) : String do\n    let d = ops(c)\n    d.route(pid, deliver)\n  end\n\n  doc \"As `route`, for every message of [type_tag] with no pid route (typed receivers).\"\n  fn route_type(c : Cap(ClusterNode.Live), type_tag : String, deliver : NodeSend.Delivery -> Result((), String)) : String do\n    let d = ops(c)\n    d.route_type(type_tag, deliver)\n  end\n\n  doc \"\"\"\n  As `route`, for a SESSION endpoint (SessionNode's parties, access points\n  and initiator inboxes): it takes session traffic (`session_tags()`) from\n  any certified peer, raw_send or not, and refuses anything else from a peer\n  where raw sends are refused. The session layer checks the rest: frames\n  carry the session id, and access points check certificates' roles.\n  \"\"\"\n  fn route_session(c : Cap(ClusterNode.Live), pid : Int, deliver : NodeSend.Delivery -> Result((), String)) : String do\n    let d = ops(c)\n    d.route_session(pid, deliver)\n  end\n\n  doc \"\"\"\n  Remove the route installed under [key] (from `route`, `route_type` or\n  `route_session`); an unknown key is a no-op. Later messages for it find no\n  route (and go back to the sender as DELIVERY_FAILED).\n  \"\"\"\n  fn unroute(c : Cap(ClusterNode.Live), key : String) : () do\n    let d = ops(c)\n    d.unroute(key)\n  end\n\n  doc \"\"\"\n  Call [f](peer_node_id, why) whenever a data connection ends, from that\n  connection's reader, after its last delivery. [why] is \"node <name> dead:\n  <cause>\" when SWIM declared the peer dead, \"replaced\" when a duplicate pair\n  was closed, else \"connection lost\". Returns an id for `off_peer_closed`.\n  \"\"\"\n  fn on_peer_closed(c : Cap(ClusterNode.Live), f : String -> String -> Unit) : Int do\n    let d = ops(c)\n    d.on_peer_closed(f)\n  end\n\n  doc \"Remove the `on_peer_closed` callback with id [id]; an unknown id is a no-op.\"\n  fn off_peer_closed(c : Cap(ClusterNode.Live), id : Int) : () do\n    let d = ops(c)\n    d.off_peer_closed(id)\n  end\n\n  doc \"\"\"\n  Call [f](seq, reason) for every DELIVERY_FAILED a peer sends back, except\n  for a session's frames (a negative seq, `session_seq`): those go to the\n  session's own handler (`on_session_failed`).\n  \"\"\"\n  fn on_delivery_failed(c : Cap(ClusterNode.Live), f : Int -> String -> Unit) : () do\n    let d = ops(c)\n    d.on_delivery_failed(f)\n  end\n\n  pfn session_seq_span() : Int do 16777216 end\n\n  doc \"\"\"\n  The wire seq of the [n]th frame a session sends under [key] (> 0, never\n  reused in this process: SessionNode draws it from a process-wide\n  counter, so a late refusal of an ended session's frame finds no handler\n  rather than another session's). Negative, so it never collides with a user's own seqs: a\n  DELIVERY_FAILED for it goes to the handler `on_session_failed` installed\n  under [key], not to `on_delivery_failed`'s.\n  \"\"\"\n  fn session_seq(key : Int, n : Int) : Int do\n    0 - (key * session_seq_span() + n % session_seq_span())\n  end\n\n  doc \"The key a `session_seq` was made under.\"\n  fn session_seq_key(seq : Int) : Int do\n    (0 - seq) / session_seq_span()\n  end\n\n  doc \"\"\"\n  Call [f](peer_node_id, reason) for every DELIVERY_FAILED a peer sends back\n  for a frame sent with a `session_seq` under [key] (a frame the peer could\n  not route: its endpoint is gone, a stale creation, or refused). Replaces\n  any handler under [key]; `off_session_failed` removes it.\n  \"\"\"\n  fn on_session_failed(c : Cap(ClusterNode.Live), key : Int, f : String -> String -> Unit) : () do\n    let d = ops(c)\n    d.on_session_failed(key, f)\n  end\n\n  doc \"\"\"\n  Remove the `on_session_failed` handler under [key]; an unknown key is a\n  no-op. A later DELIVERY_FAILED for that key's seqs then finds no handler\n  and is dropped.\n  \"\"\"\n  fn off_session_failed(c : Cap(ClusterNode.Live), key : Int) : () do\n    let d = ops(c)\n    d.off_session_failed(key)\n  end\n\n  doc \"\"\"\n  Monitor the remote process [target]: [on_down] gets its DownReason once,\n  when it exits (Normal/Killed/Crash) or when its node is declared dead\n  (NodeDown). The fire is at-least-once on the wire and delivered once here.\n  Err when this node has no link to [target]'s node.\n  \"\"\"\n  fn monitor_remote(c : Cap(ClusterNode.Live), target : GlobalPid.Pid, on_down : DistLink.DownReason -> Unit) : Result(Int, String) do\n    let d = ops(c)\n    d.monitor_remote(target, on_down)\n  end\n\n  doc \"\"\"\n  Cancel the `monitor_remote` of [target] whose ref is [r] (the `Ok` value\n  `monitor_remote` returned): its `on_down` callback is removed here, so a\n  later fire for it is ignored. Local only: no message goes to [target]'s\n  node. An unknown ref is a no-op.\n  \"\"\"\n  fn demonitor_remote(c : Cap(ClusterNode.Live), target : GlobalPid.Pid, r : Int) : () do\n    let d = ops(c)\n    d.demonitor_remote(target, r)\n  end\n\n  doc \"\"\"\n  Wait (polling every 50 ms) until at least [n] other nodes are Alive, or\n  [timeout_ms] passes. True if they are.\n  \"\"\"\n  fn await_members(c : Cap(ClusterNode.Live), n : Int, timeout_ms : Int) : Bool do\n    if List.length(members(c)) >= n do\n      true\n    else\n      if timeout_ms <= 0 do\n        false\n      else\n        sleep_ms(50)\n        await_members(c, n, timeout_ms - 50)\n      end\n    end\n  end\n\n  -- \u2500\u2500 certificates (distributed-deploys step 11a) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  The certificate peer [node_id] presented in its latest verified handshake\n  (certificate mode), or None (shared-secret mode, or no such peer). The\n  step-11b checks (session roles, raw sends, registry visibility) read it.\n  \"\"\"\n  fn peer_cert(c : Cap(ClusterNode.Live), node_id : String) : Option(NodeCert.Cert) do\n    let d = ops(c)\n    d.peer_cert(node_id)\n  end\n\n  doc \"\"\"\n  This node's own certificate (certificate mode), or None (shared-secret\n  mode). `ops_stub`'s answer is None, a shared-secret node: every step-11b\n  check is off unless a test overrides it.\n  \"\"\"\n  fn own_cert(c : Cap(ClusterNode.Live)) : Option(NodeCert.Cert) do\n    let d = ops(c)\n    d.own_cert(())\n  end\n\n  doc \"\"\"\n  Is this node in certificate mode? Every authorization check (the two-way\n  role check at session formation, raw-send denial, registry visibility)\n  applies only then; a shared-secret node checks nothing, as before step 11b.\n  \"\"\"\n  fn certified(c : Cap(ClusterNode.Live)) : Bool do own_cert(c) != None end\n\n  doc \"\"\"\n  Run the cluster link's authenticated handshake (`NetKernel.handshake_auth`)\n  on [fd], a connection that is not a cluster link, with this node's identity\n  and credentials as of now: the peer must hold the cluster secret\n  (shared-secret mode), or an operator-signed, unexpired, unrevoked\n  certificate whose key it proves (certificate mode; the result's `cert`).\n  [role] names the connection in the hello. Both ends call it. Used by the\n  control API's candidate-to-candidate verbs (`AUDIT_COPY`, `RELEASE_COPY`);\n  call `NetKernel.forget(fd)` when done, before the fd is closed.\n  \"\"\"\n  fn handshake(c : Cap(ClusterNode.Live), fd : Int, role : String, timeout_ms : Int) : Result(NetKernel.Authed, String) do\n    let d = ops(c)\n    d.handshake(fd, role, timeout_ms)\n  end\n\n  doc \"\"\"\n  May node [id] play role [role] of protocol [proto] in [mode] (\"offer\" or\n  \"initiate\")? Always Ok on a shared-secret node; on a certificate node,\n  `SessionAP.authorize` against [id]'s certificate (this node's own when\n  [id] is this node, else the peer's verified one; `Err` when the peer\n  presented none). What SessionNode's access points check\n  when a session forms.\n  \"\"\"\n  fn authorize_peer(c : Cap(ClusterNode.Live), id : String, proto : String, role : String,\n                    mode : String) : Result((), String) do\n    if certified(c) do SessionAP.authorize(peer_or_own_cert(c, id), proto, role, mode)\n    else Ok(()) end\n  end\n\n  -- The certificate of [node_id]: this node's own for its own id (the\n  -- loopback: an initiator inviting an offer on its own node), else the peer's.\n  pfn peer_or_own_cert(c : Cap(ClusterNode.Live), id : String) : Option(NodeCert.Cert) do\n    if id == node_id(c) do own_cert(c) else peer_cert(c, id) end\n  end\n\n  doc \"\"\"\n  Call [f] on every security event (see `SecurityEvent`): a handshake\n  refused (the peer's certificate did not verify, it runs in the other mode,\n  the wrong secret, ...), a frame that failed its MAC, a raw send refused,\n  and a certificate replaced or a replacement refused. Returns an id for\n  `off_security_event`.\n\n      let id = ClusterNode.on_security_event(node, fn ev ->\n        println(ClusterNode.security_text(ev)))\n  \"\"\"\n  fn on_security_event(c : Cap(ClusterNode.Live), f : SecurityEvent -> Unit) : Int do\n    let d = ops(c)\n    d.on_security_event(f)\n  end\n\n  doc \"Remove the `on_security_event` callback with id [id]; an unknown id is a no-op.\"\n  fn off_security_event(c : Cap(ClusterNode.Live), id : Int) : () do\n    let d = ops(c)\n    d.off_security_event(id)\n  end\n\n  doc \"\"\"\n  Frames from this node's peers dropped because they failed their MAC\n  (sealed connections: see specs/lang/clustering.md, \"Per-frame MAC\").\n  \"\"\"\n  fn frames_rejected(c : Cap(ClusterNode.Live)) : Int do\n    let d = ops(c)\n    d.frames_rejected(())\n  end\n\n  doc \"\"\"\n  Raw sends this node refused (certificate mode, step 11b): outbound ones\n  (`send_msg`'s `Err(NotAuthorized)`, `queue_for`'s None) and inbound raw\n  frames dropped from a peer. Each is also a `RawSendRefused` security event.\n  \"\"\"\n  fn raw_refused(c : Cap(ClusterNode.Live)) : Int do\n    let d = ops(c)\n    d.raw_refused(())\n  end\n\n  doc \"\"\"\n  Revoke a certificate cluster-wide: [token] is `forge cluster revoke`'s\n  output, signed by the operator key. The node drops any link whose\n  certificate it names (the peer is reported NodeDead(_, \"certificate\n  revoked\")), refuses that certificate's handshakes, and passes the\n  revocation on to every peer. Err for a token that does not parse or is not\n  the operator's, or on a shared-secret node.\n  \"\"\"\n  fn revoke(c : Cap(ClusterNode.Live), token : String) : Result((), String) do\n    let d = ops(c)\n    d.revoke(token)\n  end\n\n  doc \"Every revocation this node knows (from MARCH_CLUSTER_REVOCATIONS, `revoke`, or its peers).\"\n  fn revocations(c : Cap(ClusterNode.Live)) : List(NodeCert.Revocation) do\n    let d = ops(c)\n    d.revocations(())\n  end\n\n  doc \"\"\"\n  Replace this node's certificate while it runs (certificate mode;\n  distributed-deploys step 12b). [cert_text] is the new certificate in its\n  text form (`forge cluster cert`'s .cert file); [key_hex] is its node key\n  (hex, as in MARCH_NODE_KEY), or \"\" to keep the current key (a renewal made\n  with `forge cluster cert --node-key`). It must verify under the operator\n  key now, name this node and that key, and not be revoked; otherwise Err,\n  and the certificate in use is kept. The certificate and key already in use\n  are Ok and change nothing (no update is sent, no event reported).\n\n  New handshakes present it at once. Links already up are not redialled:\n  each linked peer is sent the new certificate over the link, with a proof\n  that this node holds its key, checks it as a handshake would, and holds it\n  for that link from then on -- so the link, and every session on it, stays\n  up past the old certificate's expiry. A peer too old to know the update\n  drops the link when the old certificate expires, and the redial then\n  handshakes under the new one. Reported to `on_security_event` as\n  `CertReplaced` (or `CertRefused`). `config_from_env` nodes also do this\n  on their own when the MARCH_NODE_CERT file changes (see `CnConfig`).\n  \"\"\"\n  fn replace_cert(c : Cap(ClusterNode.Live), cert_text : String, key_hex : String) : Result(NodeCert.Cert, String) do\n    let d = ops(c)\n    d.replace_cert(cert_text, key_hex)\n  end\n\nend\n";
